/* DAWAH X — ahmad, অধ্যায় 118 · খণ্ড 118 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][118]=[[23401,23401,"","","‏ ‏وَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْتُرُنِي بِرِدَائِهِ وَأَنَا أَنْظُرُ إِلَى ‏ ‏الْحَبَشَةِ ‏ ‏يَلْعَبُونَ فِي الْمَسْجِدِ حَتَّى أَكُونَ أَنَا ‏ ‏أَسْأَمُ ‏ ‏فَأَقْعُدُ فَاقْدُرُوا قَدْرَ ‏ ‏الْجَارِيَةِ ‏ ‏الْحَدِيثَةِ السِّنِّ الْحَرِيصَةِ عَلَى اللَّهْوِ ‏","","",""],[23402,23402,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏عَائِشَةُ ‏ ‏قَالَتْ ‏ ‏مَا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصُومُ مِنْ شَهْرٍ مِنْ السَّنَةِ أَكْثَرَ مِنْ صِيَامِهِ مِنْ شَعْبَانَ كَانَ يَصُومُهُ كُلَّهُ ‏","","",""],[23403,23403,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و حَدَّثَنِي ‏ ‏بُهْلُولُ بْنُ حَكِيمٍ ‏ ‏عَنِ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَالِمٌ الدَّوْسِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَائِشَةَ ‏ ‏تَقُولُ ‏ ‏لِعَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ ‏ ‏يَا ‏ ‏عَبْدَ الرَّحْمَنِ ‏ ‏أَسْبِغْ الْوُضُوءَ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏وَيْلٌ ‏ ‏لِلْأَعْقَابِ ‏ ‏مِنْ النَّارِ ‏","","",""],[23404,23404,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏عَمْرَةُ بِنْتُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَكَرَ أَنْ ‏ ‏يَعْتَكِفَ ‏ ‏الْعَشْرَ الْأَوَاخِرَ مِنْ رَمَضَانَ فَاسْتَأْذَنَتْهُ ‏ ‏عَائِشَةُ ‏ ‏فَأَذِنَ لَهَا فَأَمَرَتْ بِبِنَائِهَا ‏ ‏فَضُرِبَ ‏ ‏وَسَأَلَتْ ‏ ‏حَفْصَةُ ‏ ‏عَائِشَةَ ‏ ‏أَنْ تَسْتَأْذِنَ لَهَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَفَعَلَتْ فَأَمَرَتْ بِبِنَائِهَا ‏ ‏فَضُرِبَ ‏ ‏فَلَمَّا رَأَتْ ذَلِكَ ‏ ‏زَيْنَبُ ‏ ‏أَمَرَتْ بِبِنَائِهَا ‏ ‏فَضُرِبَ ‏ ‏قَالَتْ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا صَلَّى انْصَرَفَ فَبَصُرَ بِالْأَبْنِيَةِ فَقَالَ ‏ ‏مَا هَذِهِ قَالُوا بِنَاءُ ‏ ‏عَائِشَةَ ‏ ‏وَحَفْصَةَ ‏ ‏وَزَيْنَبَ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏آلْبِرَّ أَرَدْتُنَّ بِهَذَا مَا أَنَا بِمُعْتَكِفٍ فَرَجَعَ فَلَمَّا أَفْطَرَ ‏ ‏اعْتَكَفَ ‏ ‏عَشَرَ شَوَّالٍ ‏","","",""],[23405,23405,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏عُتْبَةُ يَعْنِي ابْنَ ضَمْرَةَ يَعْنِي ابْنَ حَبِيبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي قَيْسٍ ‏ ‏مَوْلَى ‏ ‏غُطَيْفٍ ‏ ‏أَنَّهُ ‏ ‏أَتَى ‏ ‏عَائِشَةَ أُمَّ الْمُؤْمِنِينَ ‏ ‏فَسَلَّمَ عَلَيْهَا فَقَالَتْ مَنْ الرَّجُلُ قَالَ أَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏مَوْلَى ‏ ‏غُطَيْفِ بْنِ عَازِبٍ ‏ ‏فَقَالَتْ ‏ ‏ابْنُ عُفَيْفٍ ‏ ‏فَقَالَ نَعَمْ يَا أُمَّ الْمُؤْمِنِينَ ‏ ‏فَسَأَلَهَا عَنْ الرَّكْعَتَيْنِ بَعْدَ صَلَاةِ الْعَصْرِ أَرَكَعَهُمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ لَهُ نَعَمْ ‏","","",""],[23406,23406,"","","‏ ‏وَسَأَلَهَا عَنْ ‏ ‏ذَرَارِيِّ ‏ ‏الْكُفَّارِ فَقَالَتْ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُمْ مَعَ آبَائِهِمْ فَقُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏بِلَا عَمَلٍ قَالَ اللَّهُ عَزَّ وَجَلَّ أَعْلَمُ بِمَا كَانُوا عَامِلِينَ ‏","","",""],[23407,23407,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏صَفْوَانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏رَاشِدُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَقْطَعُ صَلَاةَ الْمُسْلِمِ شَيْءٌ إِلَّا الْحِمَارُ وَالْكَافِرُ وَالْكَلْبُ وَالْمَرْأَةُ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏يَا رَسُولَ اللَّهِ لَقَدْ قُرِنَّا بِدَوَابِّ سُوءٍ ‏","","",""],[23408,23408,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏وَمُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ عُبَيْدٍ ‏ ‏قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الشُّؤْمُ ‏ ‏سُوءُ الْخُلُقِ ‏","","",""],[23409,23409,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏مُكَاتِبًا ‏ ‏لَهَا دَخَلَ عَلَيْهَا بِبَقِيَّةِ ‏ ‏مُكَاتَبَتِهِ ‏ ‏فَقَالَتْ لَهُ أَنْتَ غَيْرُ دَاخِلٍ عَلَيَّ غَيْرَ مَرَّتِكَ هَذِهِ فَعَلَيْكَ بِالْجِهَادِ فِي سَبِيلِ اللَّهِ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا خَالَطَ قَلْبَ امْرِئٍ مُسْلِمٍ ‏ ‏رَهَجٌ فِي سَبِيلِ اللَّهِ إِلَّا حَرَّمَ اللَّهُ عَلَيْهِ النَّارَ ‏","","",""],[23410,23410,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا خُيِّرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ أَمْرَيْنِ فِي الْإِسْلَامِ إِلَّا اخْتَارَ أَيْسَرَهُمَا ‏","","",""],[23411,23411,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏ثَوَّبَ ‏ ‏الْمُؤَذِّنُ صَلَّى رَكْعَتَيْنِ خَفِيفَتَيْنِ ثُمَّ اضْطَجَعَ عَلَى شِقِّهِ الْأَيْمَنِ حَتَّى يَأْتِيَهُ الْمُؤَذِّنُ فَيُؤْذِنَهُ بِالصَّلَاةِ ‏","","",""],[23412,23412,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا ‏ ‏سَبَّحَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُبْحَةَ ‏ ‏الضُّحَى فِي سَفَرٍ وَلَا حَضَرٍ ‏","","",""],[23413,23413,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حُجْرَتِي ‏ ‏يَسْتُرُنِي بِرِدَائِهِ وَأَنَا أَنْظُرُ إِلَى ‏ ‏الْحَبَشَةِ ‏ ‏كَيْفَ يَلْعَبُونَ حَتَّى أَكُونَ أَنَا ‏ ‏أَسْأَمُ ‏ ‏وَاقْدُرْ قَدْرَ الْجَارِيَةِ الْحَدِيثَةِ السِّنِّ الْحَرِيصَةِ عَلَى اللَّهْوِ ‏","","",""],[23414,23414,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يُحِبُّ الرِّفْقَ فِي الْأَمْرِ كُلِّهِ ‏","","",""],[23415,23415,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الْعَصْرَ وَإِنَّ الشَّمْسَ لَطَالِعَةٌ فِي حُجْرَتِي ‏","","",""],[23416,23416,"","","‏ ‏حَدَّثَنَا ‏ ‏بُهْلُولُ بْنُ حَكِيمٍ الْقَرْقَسَانِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَادَ أَنْ يَنَامَ تَوَضَّأَ وُضُوءَهُ لِلصَّلَاةِ ‏","","",""],[23417,23417,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏اتَّخَذْتُ ‏ ‏دُرْنُوكًا ‏ ‏فِيهِ الصُّوَرُ فَجَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَهَتَكَهُ وَقَالَ ‏ ‏إِنَّ أَشَدَّ النَّاسِ عَذَابًا يَوْمَ الْقِيَامَةِ الَّذِينَ يُشَبِّهُونَ بِخَلْقِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[23418,23418,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَفْتِلُ ‏ ‏قَلَائِدَ ‏ ‏هَدْيِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدَيَّ ثُمَّ لَا يَعْتَزِلُ شَيْئًا وَلَا يَتْرُكُهُ إِنَّا لَا نَعْلَمُ الْحَرَامَ يُحِلُّهُ إِلَّا الطَّوَافُ ‏ ‏بِالْبَيْتِ ‏","","",""],[23419,23419,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَمَّا أَفَاضَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرَادَ مِنْ ‏ ‏صَفِيَّةَ ‏ ‏بَعْضَ مَا يُرِيدُ الرَّجُلُ مِنْ أَهْلِهِ فَقِيلَ لَهُ ‏ ‏إِنَّهَا حَائِضٌ فَقَالَ ‏ ‏عَقْرَى ‏ ‏أَحَابِسَتُنَا ‏ ‏هِيَ قَالُوا إِنَّهَا قَدْ طَافَتْ يَوْمَ النَّحْرِ ‏ ‏فَنَفَرَ ‏ ‏بِهَا ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ابْنُ مُصْعَبٍ ‏ ‏مَا سَمِعْتُهُ يَذْكُرُ ‏ ‏يَعْنِي ‏ ‏الْأَوْزَاعِيَّ ‏ ‏مُحَمَّدَ بْنَ إِبْرَاهِيمَ ‏ ‏إِلَّا مَرَّةً ‏","","",""],[23420,23420,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَيَّاشٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ وَأَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏وَاللَّهِ مَا ‏ ‏سَبَّحَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُبْحَةَ ‏ ‏الضُّحَى قَطُّ وَإِنِّي ‏ ‏لَأُسَبِّحُهَا ‏ ‏وَقَالَتْ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَتْرُكُ الْعَمَلَ وَهُوَ يُحِبُّ أَنْ يَعْمَلَهُ خَشْيَةَ أَنْ ‏ ‏يَسْتَنَّ ‏ ‏بِهِ النَّاسُ فَيُفْرَضُ عَلَيْهِمْ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحِبُّ مَا خَفَّ عَلَى النَّاسِ مِنْ الْفَرَائِضِ ‏","","",""],[23421,23421,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَيَّاشٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُطَرِّفٍ أَبُو غَسَّانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أَمَرَنِي نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏أَتَصَدَّقَ ‏ ‏بِذَهَبٍ كَانَتْ عِنْدَنَا فِي مَرَضِهِ قَالَتْ فَأَفَاقَ فَقَالَ مَا فَعَلْتِ قَالَتْ لَقَدْ شَغَلَنِي مَا رَأَيْتُ مِنْكَ قَالَ ‏ ‏فَهَلُمِّيهَا قَالَ فَجَاءَتْ بِهَا إِلَيْهِ سَبْعَةَ ‏ ‏أَوْ تِسْعَةَ ‏ ‏أَبُو حَازِمٍ ‏ ‏يَشُكُّ ‏ ‏دَنَانِيرَ فَقَالَ حِينَ جَاءَتْ بِهَا مَا ظَنُّ ‏ ‏مُحَمَّدٍ ‏ ‏أَنْ لَوْ لَقِيَ اللَّهَ عَزَّ وَجَلَّ وَهَذِهِ عِنْدَهُ وَمَا ‏ ‏تُبْقِي هَذِهِ مِنْ ‏ ‏مُحَمَّدٍ ‏ ‏لَوْ لَقِيَ اللَّهَ عَزَّ وَجَلَّ وَهَذِهِ عِنْدَهُ ‏","","",""],[23422,23422,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَيَّاشٍ ‏ ‏وَحُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُطَرِّفٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو حَازِمٍ ‏ ‏قَالَ ‏ ‏حُسَيْنٌ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ يَمُرُّ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هِلَالٌ وَهِلَالٌ وَهِلَالٌ ‏ ‏مَا يُوقَدُ فِي بَيْتٍ مِنْ بُيُوتِهِ نَارٌ قُلْتُ يَا خَالَةُ عَلَى أَيِّ شَيْءٍ كُنْتُمْ تَعِيشُونَ قَالَتْ عَلَى ‏ ‏الْأَسْوَدَيْنِ ‏ ‏التَّمْرِ وَالْمَاءِ ‏ ‏قَالَ ‏ ‏حُسَيْنٌ ‏ ‏إِنَّهُ سَمِعَ ‏ ‏عَائِشَةَ ‏ ‏تَقُولُ ‏ ‏إِنَّهُ كَانَ يَمُرُّ بِنَا هِلَالٌ وَهِلَالٌ مَا يُوقَدُ فِي بَيْتٍ مِنْ بُيُوتِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَارٌ فَقُلْتُ يَا خَالَةُ مِثْلَهُ ‏","","",""],[23423,23423,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الزُّهْرِيُّ ‏ ‏وَعَطَاءُ بْنُ أَبِي رَبَاحٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي مِنْ اللَّيْلِ وَأَنَا مُعْتَرِضَةٌ بَيْنَهُ وَبَيْنَ الْقِبْلَةِ ‏","","",""],[23424,23424,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏دَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا مُسْتَتِرَةٌ ‏ ‏بِقِرَامٍ ‏ ‏فِيهِ صُورَةٌ فَهَتَكَهُ ثُمَّ قَالَ ‏ ‏إِنَّ أَشَدَّ النَّاسِ عَذَابًا يَوْمَ الْقِيَامَةِ الَّذِينَ يُشَبِّهُونَ بِخَلْقِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[23425,23425,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْتِينِي وَهُوَ ‏ ‏مُعْتَكِفٌ ‏ ‏فِي ‏ ‏الْمَسْجِدِ ‏ ‏حَتَّى يَتَّكِئَ عَلَى بَابِ حُجْرَتِي فَأَغْسِلُ رَأْسَهُ وَأَنَا فِي حُجْرَتِي وَسَائِرُ جَسَدِهِ فِي الْمَسْجِدَ ‏","","",""],[23426,23426,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو عُبَيْدٍ ‏ ‏قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏دَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِسَرِفَ ‏ ‏وَقَدْ ‏ ‏نَفِسْتُ ‏ ‏وَأَنَا ‏ ‏مُنَكِّسَةٌ ‏ ‏فَقَالَ لِي ‏ ‏أَنَفِسْتِ ‏ ‏فَقُلْتُ نَعَمْ يَا رَسُولَ اللَّهِ وَلَا أَحْسِبُ النِّسَاءَ خُلِقْنَ إِلَّا لِلشَّرِّ فَقَالَ لَا وَلَكِنَّهُ شَيْءٌ ابْتُلِيَ بِهِ نِسَاءُ بَنِي ‏ ‏آدَمَ ‏","","",""],[23427,23427,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ سُلَيْمَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏رَبِيعَةُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَامِرٍ ‏ ‏عَنْ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أَرْسَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏فَأَقْبَلَ عَلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا رَأَيْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَقْبَلَتْ إِحْدَانَا عَلَى الْأُخْرَى فَكَانَ مِنْ آخِرِ كَلَامٍ كَلَّمَهُ أَنْ ضَرَبَ مَنْكِبَهُ وَقَالَ يَا ‏ ‏عُثْمَانُ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ ‏ ‏عَسَى أَنْ يُلْبِسَكَ قَمِيصًا فَإِنْ أَرَادَكَ الْمُنَافِقُونَ عَلَى خَلْعِهِ فَلَا تَخْلَعْهُ حَتَّى ‏ ‏تَلْقَانِي يَا ‏ ‏عُثْمَانُ ‏ ‏إِنَّ اللَّهَ عَسَى أَنْ يُلْبِسَكَ قَمِيصًا فَإِنْ أَرَادَكَ الْمُنَافِقُونَ عَلَى خَلْعِهِ فَلَا تَخْلَعْهُ حَتَّى ‏ ‏تَلْقَانِي ثَلَاثًا فَقُلْتُ لَهَا يَا أُمَّ الْمُؤْمِنِينَ فَأَيْنَ كَانَ هَذَا عَنْكِ قَالَتْ نَسِيتُهُ وَاللَّهِ فَمَا ذَكَرْتُهُ قَالَ فَأَخْبَرْتُهُ ‏ ‏مُعَاوِيَةَ بْنَ أَبِي سُفْيَانَ ‏ ‏فَلَمْ يَرْضَ بِالَّذِي أَخْبَرْتُهُ حَتَّى كَتَبَ إِلَى أُمِّ الْمُؤْمِنِينَ أَنْ اكْتُبِي إِلَيَّ بِهِ فَكَتَبَتْ إِلَيْهِ بِهِ كِتَابًا ‏","","",""],[23428,23428,"","","‏ ‏حَدَّثَنَا ‏ ‏عِصَامُ بْنُ خَالِدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ ثَابِتِ بْنِ ثَوْبَانَ ‏ ‏عَمَّنْ ‏ ‏سَمِعَ ‏ ‏مَكْحُولًا ‏ ‏يُحَدِّثُ عَنْ ‏ ‏مَسْرُوقِ بْنِ الْأَجْدَعِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏شَرِبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَائِمًا وَقَاعِدًا وَمَشَى حَافِيًا وَنَاعِلًا وَانْصَرَفَ عَنْ يَمِينِهِ وَعَنْ شِمَالِهِ ‏","","",""],[23429,23429,"","","‏ ‏حَدَّثَنَا ‏ ‏بِشْرُ بْنُ شُعَيْبِ بْنِ أَبِي حَمْزَةَ ‏ ‏قَالَ وَأَخْبَرَنِي ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏أَخْبَرَنِي ‏ ‏عُرْوَةُ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏أَخْبَرَتْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِلْوَزَغِ ‏ ‏فُوَيْسِقٌ ‏ ‏وَلَمْ أَسْمَعْهُ أَمَرَ بِقَتْلِهِ ‏","","",""],[23430,23430,"","","‏ ‏حَدَّثَنَا ‏ ‏بِشْرُ بْنُ شُعَيْبٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَمَّا يَقْتُلُ الْمُحْرِمُ مِنْ الدَّوَابِّ ‏ ‏قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَمْسٌ مِنْ الدَّوَابِّ كُلُّهُنَّ فَاسِقٌ يُقْتَلْنَ فِي ‏ ‏الْحَرَمِ ‏ ‏الْكَلْبُ ‏ ‏الْعَقُورُ ‏ ‏وَالْعَقْرَبُ وَالْحُدَيَّا وَالْغُرَابُ وَالْفَأْرَةُ ‏","","",""],[23431,23431,"","","‏ ‏حَدَّثَنَا ‏ ‏بِشْرُ بْنُ شُعَيْبٍ ‏ ‏قَالَ فَحَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏وَأَخْبَرَنِي ‏ ‏يَحْيَى بْنُ عُرْوَةَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عُرْوَةَ ‏ ‏يَقُولُ قَالَتْ ‏ ‏عَائِشَةُ زَوْجُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَأَلَ أُنَاسٌ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْكُهَّانِ ‏ ‏فَقَالَ لَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسُوا بِشَيْءٍ فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّهُمْ يُحَدِّثُونَ أَحْيَانًا بِالشَّيْءِ يَكُونُ حَقًّا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تِلْكَ الْكَلِمَةُ مِنْ الْحَقِّ يَخْطَفُهَا الْجِنِّيُّ ‏ ‏فَيُقِرُّهَا ‏ ‏فِي أُذُنِ وَلِيِّهِ ‏ ‏قَرَّ ‏ ‏الدَّجَاجَةِ فَيَخْلِطُونَ فِيهَا أَكْثَرَ مِنْ مِائَةِ كَذْبَةٍ ‏","","",""],[23432,23432,"","","‏ ‏حَدَّثَنَا ‏ ‏بِشْرُ بْنُ شُعَيْبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏كَسَفَتْ الشَّمْسُ فِي حَيَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَخَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى الْمَسْجِدِ فَقَامَ فَكَبَّرَ وَصَفَّ النَّاسُ وَرَاءَهُ فَكَبَّرَ وَاقْتَرَأَ قِرَاءَةً طَوِيلَةً ثُمَّ كَبَّرَ فَرَكَعَ رُكُوعًا طَوِيلًا ثُمَّ قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ فَقَامَ وَلَمْ يَسْجُدْ فَاقْتَرَأَ قِرَاءَةً طَوِيلَةً هِيَ أَدْنَى مِنْ الْقِرَاءَةِ الْأُولَى ثُمَّ كَبَّرَ وَرَكَعَ رُكُوعًا طَوِيلًا هُوَ أَدْنَى مِنْ الرُّكُوعِ الْأَوَّلِ ثُمَّ قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ رَبَّنَا لَكَ الْحَمْدُ ثُمَّ سَجَدَ ثُمَّ فَعَلَ فِي الرَّكْعَةِ الْأُخْرَى مِثْلَ ذَلِكَ فَاسْتَكْمَلَ أَرْبَعَ رَكَعَاتٍ وَأَرْبَعَ سَجَدَاتٍ وَانْجَلَتْ الشَّمْسُ قَبْلَ أَنْ يَنْصَرِفَ ثُمَّ قَامَ فَأَثْنَى عَلَى اللَّهِ عَزَّ وَجَلَّ بِمَا هُوَ أَهْلُهُ ثُمَّ قَالَ إِنَّمَا ‏ ‏هُمَا آيَتَانِ مِنْ آيَاتِ اللَّهِ عَزَّ وَجَلَّ لَا يَنْخَسِفَانِ لِمَوْتِ أَحَدٍ وَلَا لِحَيَاتِهِ فَإِذَا رَأَيْتُمُوهُمَا ‏ ‏فَافْزَعُوا ‏ ‏لِلصَّلَاةِ ‏ ‏وَكَانَ ‏ ‏كَثِيرُ بْنُ عَبَّاسٍ ‏ ‏يُحَدِّثُ أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عَبَّاسٍ ‏ ‏كَانَ يُحَدِّثُ عَنْ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ كَسَفَتْ الشَّمْسُ ‏ ‏مِثْلَ مَا حَدَّثَ ‏ ‏عُرْوَةُ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ ‏ ‏لِعُرْوَةَ ‏ ‏فَإِنَّ أَخَاكَ يَوْمَ كَسَفَتْ الشَّمْسُ ‏ ‏بِالْمَدِينَةِ ‏ ‏لَمْ يَزِدْ عَلَى رَكْعَتَيْنِ مِثْلَ صَلَاةِ الصُّبْحِ فَقَالَ أَجَلْ إِنَّهُ أَخْطَأَ السُّنَّةَ ‏","","",""],[23433,23433,"","","‏ ‏حَدَّثَنَا ‏ ‏بِشْرُ بْنُ شُعَيْبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي بَكْرِ بْنِ حَزْمٍ ‏ ‏أَنَّ ‏ ‏عُرْوَةَ بْنَ الزُّبَيْرِ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏جَاءَتْ امْرَأَةٌ وَمَعَهَا ابْنَتَانِ لَهَا تَسْأَلُنِي فَلَمْ تَجِدْ عِنْدِي شَيْئًا غَيْرَ تَمْرَةٍ وَاحِدَةٍ فَأَعْطَيْتُهَا إِيَّاهَا فَأَخَذَتْهَا فَشَقَّتْهَا بِاثْنَيْنِ بَيْنَ ابْنَتَيْهَا وَلَمْ تَأْكُلْ مِنْهَا شَيْئًا ثُمَّ قَامَتْ فَخَرَجَتْ هِيَ وَابْنَتَاهَا فَدَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَحَدَّثْتُهُ حَدِيثَهَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ابْتُلِيَ مِنْ الْبَنَاتِ بِشَيْءٍ فَأَحْسَنَ إِلَيْهِنَّ كُنَّ لَهُ سِتْرًا مِنْ النَّارِ ‏","","",""],[23434,23434,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ مُصِيبَةٍ تُصِيبُ الْمُسْلِمَ إِلَّا كَفَّرَ اللَّهُ عَزَّ وَجَلَّ بِهَا عَنْهُ حَتَّى الشَّوْكَةُ يُشَاكُهَا ‏","","",""],[23435,23435,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏عَائِشُ ‏ ‏هَذَا ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏وَهُوَ يَقْرَأُ عَلَيْكِ السَّلَامَ فَقَالَتْ وَعَلَيْهِ السَّلَامُ وَرَحْمَةُ اللَّهِ قَالَتْ وَهُوَ يَرَى مَا لَا نَرَى ‏","","",""],[23436,23436,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏أَرْسَلَ أَزْوَاجُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاطِمَةَ بِنْتَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاسْتَأْذَنَتْ وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَعَ ‏ ‏عَائِشَةَ ‏ ‏فِي ‏ ‏مِرْطِهَا ‏ ‏فَأَذِنَ لَهَا فَدَخَلَتْ عَلَيْهِ فَقَالَتْ يَا رَسُولَ اللَّهِ إِنَّ أَزْوَاجَكَ أَرْسَلْنَنِي إِلَيْكَ يَسْأَلْنَكَ الْعَدْلَ فِي ‏ ‏ابْنَةِ أَبِي قُحَافَةَ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيْ بُنَيَّةُ ‏ ‏أَلَسْتِ تُحِبِّينَ مَا أُحِبُّ فَقَالَتْ بَلَى فَقَالَ فَأَحِبِّي هَذِهِ ‏ ‏لِعَائِشَةَ ‏ ‏قَالَتْ فَقَامَتْ ‏ ‏فَاطِمَةُ ‏ ‏فَخَرَجَتْ فَجَاءَتْ أَزْوَاجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَحَدَّثَتْهُنَّ بِمَا قَالَتْ وَبِمَا قَالَ لَهَا فَقُلْنَ لَهَا مَا ‏ ‏أَغْنَيْتِ ‏ ‏عَنَّا مِنْ شَيْءٍ فَارْجِعِي إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ ‏ ‏فَاطِمَةُ ‏ ‏عَلَيْهَا السَّلَام ‏ ‏وَاللَّهِ لَا أُكَلِّمُهُ فِيهَا أَبَدًا فَأَرْسَلَ أَزْوَاجُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَيْنَبَ بِنْتَ جَحْشٍ ‏ ‏فَاسْتَأْذَنَتْ فَأَذِنَ لَهَا فَدَخَلَتْ فَقَالَتْ يَا رَسُولَ اللَّهِ أَرْسَلَنِي إِلَيْكَ أَزْوَاجُكَ يَسْأَلْنَكَ الْعَدْلَ فِي ‏ ‏ابْنَةِ أَبِي قُحَافَةَ ‏ ‏قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏ثُمَّ ‏ ‏وَقَعَتْ ‏ ‏بِي ‏ ‏زَيْنَبُ ‏ ‏قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَطَفِقْتُ ‏ ‏أَنْظُرُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَتَى يَأْذَنُ لِي فِيهَا فَلَمْ أَزَلْ حَتَّى عَرَفْتُ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَكْرَهُ أَنْ أَنْتَصِرَ قَالَتْ ‏ ‏فَوَقَعْتُ ‏ ‏بِزَيْنَبَ ‏ ‏فَلَمْ ‏ ‏أَنْشَبْهَا ‏ ‏أَنْ أَفْحَمْتُهَا فَتَبَسَّمَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ إِنَّهَا ‏ ‏ابْنَةُ أَبِي بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أَرْسَلَ أَزْوَاجُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاطِمَةَ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[23437,23437,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏أَخْبَرَتْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي إِحْدَى عَشْرَةَ رَكْعَةً بِاللَّيْلِ كَانَتْ تِلْكَ صَلَاتَهُ يَسْجُدُ السَّجْدَةَ مِنْ ذَلِكَ بِقَدْرِ مَا يَقْرَأُ أَحَدُكُمْ خَمْسِينَ آيَةً قَبْلَ أَنْ يَرْفَعَ رَأْسَهُ وَيَرْكَعُ رَكْعَتَيْنِ قَبْلَ صَلَاةِ الْفَجْرِ ثُمَّ يَضْطَجِعُ عَلَى شِقِّهِ الْأَيْمَنِ حَتَّى يَأْتِيَهُ الْمُنَادِي لِلصَّلَاةِ ‏","","",""],[23438,23438,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ وَأَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْبَرَتْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَدْعُو فِي الصَّلَاةِ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ وَأَعُوذُ بِكَ مِنْ فِتْنَةِ ‏ ‏الْمَسِيحِ الدَّجَّالِ ‏ ‏وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَحْيَا وَفِتْنَةِ الْمَمَاتِ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ ‏ ‏الْمَأْثَمِ ‏ ‏وَالْمَغْرَمِ ‏ ‏قَالَتْ فَقَالَ لَهُ قَائِلٌ مَا أَكْثَرَ مَا تَسْتَعِيذُ مِنْ ‏ ‏الْمَغْرَمِ ‏ ‏يَا رَسُولَ اللَّهِ فَقَالَ إِنَّ الرَّجُلَ إِذَا ‏ ‏غَرِمَ ‏ ‏حَدَّثَ فَكَذَبَ وَوَعَدَ فَأَخْلَفَ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ يَعْنِي ابْنَ الْهَادِ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدْعُو فِي الصَّلَاةِ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[23439,23439,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سَعِيدُ بْنُ خَالِدِ بْنِ عَمْرِو بْنِ عُثْمَانَ بْنِ عَفَّانَ ‏ ‏وَأَنَا أُحَدِّثُهُ هَذِهِ الْأَحَادِيثَ أَنَّهُ سَأَلَ ‏ ‏عُرْوَةَ بْنَ الزُّبَيْرِ ‏ ‏عَمَّا مَسَّتْ النَّارُ ‏ ‏فَقَالَ ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏سَمِعْتُ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّئُوا مِمَّا مَسَّتْ النَّارُ ‏","","",""],[23440,23440,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْبَرَتْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ تُوُفِّيَ ‏ ‏سُجِّيَ ‏ ‏بِثَوْبٍ ‏ ‏حِبَرَةٍ ‏","","",""],[23441,23441,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏دَخَلَ عَلَيَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعِنْدِي امْرَأَةٌ مِنْ ‏ ‏الْيَهُودِ ‏ ‏وَهِيَ تَقُولُ لِي أَشَعَرْتِ أَنَّكُمْ ‏ ‏تُفْتَنُونَ ‏ ‏فِي الْقُبُورِ ‏ ‏فَارْتَاعَ ‏ ‏النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ إِنَّمَا ‏ ‏تُفْتَنُ ‏ ‏الْيَهُودُ ‏ ‏فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَلَبِثْنَا ‏ ‏لَيَالِيَ ثُمَّ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ شَعَرْتِ أَنَّهُ أُوحِيَ إِلَيَّ أَنَّكُمْ ‏ ‏تُفْتَنُونَ ‏ ‏فِي الْقُبُورِ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَسَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَ ذَلِكَ ‏ ‏يَسْتَعِيذُ مِنْ عَذَابِ الْقَبْرِ ‏","","",""],[23442,23442,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ قَالَ ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏إِنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ صَحِيحٌ يَقُولُ إِنَّهُ ‏ ‏لَمْ يُقْبَضْ نَبِيٌّ قَطُّ حَتَّى يَرَى مَقْعَدَهُ مِنْ الْجَنَّةِ ثُمَّ ‏ ‏يَحْيَا فَلَمَّا اشْتَكَى وَحَضَرَهُ الْقَبْضُ وَرَأْسُهُ عَلَى فَخْذِ ‏ ‏عَائِشَةَ ‏ ‏غُشِيَ عَلَيْهِ فَلَمَّا أَفَاقَ ‏ ‏شَخَصَ ‏ ‏بَصَرُهُ نَحْوَ سَقْفِ الْبَيْتِ ثُمَّ قَالَ اللَّهُمَّ الرَّفِيقَ الْأَعْلَى قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَقُلْتُ إِنَّهُ حَدِيثُهُ الَّذِي كَانَ يُحَدِّثُنَا وَهُوَ صَحِيحٌ ‏","","",""],[23443,23443,"","","‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ بْنُ شُرَيْحٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بَقِيَّةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بَحِيرُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏أَنَّ ‏ ‏رَجُلًا سَأَلَ ‏ ‏عَائِشَةَ ‏ ‏عَنْ الصِّيَامِ ‏ ‏فَقَالَتْ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَصُومُ شَعْبَانَ وَكَانَ ‏ ‏يَتَحَرَّى ‏ ‏صِيَامَ يَوْمِ الْخَمِيسِ ‏ ‏وَالِاثْنَيْنِ ‏","","",""],[23444,23444,"","","‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ بْنُ شُرَيْحٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بَقِيَّةُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏بَحِيرُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنْ ‏ ‏أَبِي زِيَادٍ خِيَارِ بْنِ سَلَمَةَ ‏ ‏أَنَّهُ ‏ ‏سَأَلَ ‏ ‏عَائِشَةَ ‏ ‏عَنْ الْبَصَلِ فَقَالَتْ ‏ ‏إِنَّ آخِرَ طَعَامٍ أَكَلَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طَعَامٌ فِيهِ بَصَلٌ ‏","","",""],[23445,23445,"","","‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ بْنُ شُرَيْحٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بَقِيَّةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي قَيْسٍ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عَائِشَةَ ‏ ‏تَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْوِصَالِ ‏ ‏فِي الصِّيَامِ ‏","","",""],[23446,23446,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ وَمَلَائِكَتَهُ ‏ ‏عَلَيْهِمْ السَّلَام ‏ ‏يُصَلُّونَ عَلَى الَّذِينَ يَصِلُونَ الصُّفُوفَ وَمَنْ سَدَّ فُرْجَةً رَفَعَهُ اللَّهُ بِهَا دَرَجَةً ‏","","",""],[23447,23447,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ عَبْدِ رَبِّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بَقِيَّةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الزُّبَيْدِيُّ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَبْعَثُ اللَّهُ عَزَّ وَجَلَّ النَّاسَ يَوْمَ الْقِيَامَةِ حُفَاةً عُرَاةً ‏ ‏غُرْلًا ‏ ‏قَالَ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏يَا رَسُولَ اللَّهِ فَكَيْفَ بِالْعَوْرَاتِ قَالَ ‏ { ‏لِكُلِّ امْرِئٍ مِنْهُمْ يَوْمَئِذٍ شَأْنٌ يُغْنِيهِ ‏}","","",""],[23448,23448,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ عَبْدِ رَبِّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا رَأَى الْمَطَرَ قَالَ اللَّهُمَّ اجْعَلْهُ صَيِّبًا هَنِيئًا ‏","","",""],[23449,23449,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ بَحْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا رَأَى الْمَطَرَ قَالَ اللَّهُمَّ اجْعَلْهُ ‏ ‏صَيِّبًا ‏ ‏هَنِيئًا ‏","","",""],[23450,23450,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ بَحْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْبَلُ الْهَدِيَّةَ وَيُثِيبُ عَلَيْهَا ‏","","",""],[23451,23451,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ بَحْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو خَالِدٍ الْأَحْمَرُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أَفَاضَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ آخِرِ يَوْمِهِ حِينَ صَلَّى الظُّهْرَ ثُمَّ رَجَعَ إِلَى ‏ ‏مِنًى ‏ ‏فَمَكَثَ بِهَا ‏ ‏لَيَالِيَ أَيَّامِ التَّشْرِيقِ ‏ ‏يَرْمِي الْجَمْرَةَ إِذَا ‏ ‏زَالَتْ ‏ ‏الشَّمْسُ كُلُّ جَمْرَةٍ بِسَبْعِ حَصَيَاتٍ يُكَبِّرُ مَعَ كُلِّ حَصَاةٍ وَيَقِفُ عِنْدَ الْأُولَى وَعِنْدَ الثَّانِيَةِ فَيُطِيلُ الْقِيَامَ وَيَتَضَرَّعُ ‏ ‏وَيَرْمِي الثَّالِثَةَ لَا يَقِفُ عِنْدَهَا ‏","","",""],[23452,23452,"","","‏ ‏حَدَّثَنَا ‏ ‏سَكَنُ بْنُ نَافِعٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏صَالِحُ بْنُ أَبِي الْأَخْضَرِ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَتَى إِلَيْهِ مَعْرُوفٌ فَلْيُكَافِئْ بِهِ وَمَنْ لَمْ يَسْتَطِعْ فَلْيَذْكُرْهُ فَمَنْ ذَكَرَهُ فَقَدْ شَكَرَهُ وَمَنْ تَشَبَّعَ بِمَا لَمْ يَنَلْ فَهُوَ كَلَابِسِ ثَوْبَيْ زُورٍ ‏","","",""],[23453,23453,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جَعْفَرِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏إِذَا دَهَنْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدَعْتُ ‏ ‏فَرْقَةً ‏ ‏مِنْ فَوْقِ ‏ ‏يَافُوخِهِ ‏ ‏وَأَرْسَلْتُ لَهُ ‏ ‏نَاصِيَةً ‏","","",""],[23454,23454,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَبْدِ اللَّهِ بْنِ أُسَامَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَبِي عَمْرٍو ‏ ‏عَنْ ‏ ‏الْمُطَّلِبِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ الْمُؤْمِنَ لَيُدْرِكُ بِحُسْنِ خُلُقِهِ دَرَجَاتِ قَائِمِ اللَّيْلِ صَائِمِ النَّهَارِ ‏","","",""],[23455,23455,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ سَعِيدٍ يَعْنِي ابْنَ عَمْرِو بْنِ سَعِيدِ بْنِ الْعَاصِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏دَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَقُولُ يَا ‏ ‏عَائِشَةُ ‏ ‏قَوْمُكِ أَسْرَعُ أُمَّتِي بِي لَحَاقًا قَالَتْ فَلَمَّا جَلَسَ قُلْتُ يَا رَسُولَ اللَّهِ جَعَلَنِي اللَّهُ فِدَاءَكَ لَقَدْ دَخَلْتَ وَأَنْتَ تَقُولُ كَلَامًا ذَعَرَنِي فَقَالَ وَمَا هُوَ قَالَتْ تَزْعُمُ أَنَّ قَوْمِي أَسْرَعُ أُمَّتِكَ بِكَ لَحَاقًا قَالَ نَعَمْ قَالَتْ وَعَمَّ ذَاكَ قَالَ تَسْتَحْلِيهِمْ ‏ ‏الْمَنَايَا ‏ ‏فَتَنَفَّسُ عَلَيْهِمْ أُمَّتُهُمْ قَالَتْ فَقُلْتُ فَكَيْفَ النَّاسُ بَعْدَ ذَلِكَ ‏ ‏أَوْ عِنْدَ ذَلِكَ ‏ ‏قَالَ دَبًى يَأْكُلُ شِدَادُهُ ضِعَافَهُ حَتَّى تَقُومَ عَلَيْهِمْ السَّاعَةُ ‏ ‏وَالدَّبَى ‏ ‏الْجَنَادِبُ ‏ ‏الَّتِي لَمْ تَنْبُتْ أَجْنِحَتُهَا ‏","","",""],[23456,23456,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قِيلَ ‏ ‏لِعَائِشَةَ ‏ ‏يَا أُمَّ الْمُؤْمِنِينَ هَذَا الشَّهْرُ تِسْعٌ وَعِشْرُونَ قَالَتْ وَمَا يُعْجِبُكُمْ مِنْ ذَلِكَ لَمَا ‏ ‏صُمْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تِسْعًا وَعِشْرِينَ أَكْثَرُ مِمَّا صُمْتُ ثَلَاثِينَ ‏","","",""],[23457,23457,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الْهَاشِمِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏الْحُمَّى ‏ ‏مِنْ ‏ ‏فَيْحِ ‏ ‏جَهَنَّمَ فَأَبْرِدُوهَا بِالْمَاءِ ‏ ‏قَالَ ‏ ‏إِبْرَاهِيمُ ‏ ‏لَمْ أَسْمَعْ مِنْ ‏ ‏هِشَامٍ ‏ ‏شَيْئًا إِلَّا هَذَا الْحَدِيثَ الْوَاحِدَ ‏","","",""],[23458,23458,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْمُبَارَكُ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏أُمِّي ‏ ‏عَنْ ‏ ‏مُعَاذَةَ الْعَدَوِيَّةِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا أَخْبَرَتْهَا قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَغْتَسِلُ أَنَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ إِنَاءٍ وَاحِدٍ وَأَنَا أَقُولُ لَهُ أَبْقِ لِي أَبْقِ لِي ‏","","",""],[23459,23459,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ طَلْحَةَ ‏ ‏عَنْ ‏ ‏زُبَيْدٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا زَالَ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏يُوصِينِي بِالْجَارِ حَتَّى ظَنَنْتُ أَنَّهُ يُوَرِّثُهُ ‏","","",""],[23460,23460,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُبَارَكٌ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ هِشَامِ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ ‏ ‏عَائِشَةَ ‏ ‏فَقُلْتُ يَا أُمَّ الْمُؤْمِنِينَ ‏ ‏أَخْبِرِينِي بِخُلُقِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ كَانَ خُلُقُهُ الْقُرْآنَ أَمَا تَقْرَأُ الْقُرْآنَ قَوْلَ اللَّهِ عَزَّ وَجَلَّ ‏ { ‏وَإِنَّكَ لَعَلَى خُلُقٍ عَظِيمٍ ‏} ‏قُلْتُ فَإِنِّي أُرِيدُ أَنْ أَتَبَتَّلَ قَالَتْ لَا تَفْعَلْ أَمَا تَقْرَأُ ‏ { ‏لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ ‏} ‏فَقَدْ تَزَوَّجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَدْ وُلِدَ لَهُ ‏","","",""],[23461,23461,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَوْ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى مِنْ النِّسَاءِ مَا رَأَيْنَا لَمَنَعَهُنَّ مِنْ الْمَسَاجِدِ كَمَا مَنَعَتْ ‏ ‏بَنُو إِسْرَائِيلَ ‏ ‏نِسَاءَهَا ‏ ‏قُلْتْ ‏ ‏لِعَمْرَةَ ‏ ‏وَمَنَعَتْ ‏ ‏بَنُو إِسْرَائِيلَ ‏ ‏نِسَاءَهَا قَالَتْ نَعَمْ ‏","","",""],[23462,23462,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَأَنِّي أَنْظُرُ إِلَيَّ ‏ ‏أَفْتِلُ ‏ ‏قَلَائِدَ ‏ ‏هَدْيِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الْغَنَمِ ثُمَّ لَا يُمْسِكُ عَنْ شَيْءٍ ‏","","",""],[23463,23463,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏الْمُعَلَّى بْنِ زِيَادٍ ‏ ‏وَهِشَامٍ ‏ ‏وَيُونُسَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏دَعَوَاتٌ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُكْثِرُ أَنْ يَدْعُوَ بِهَا ‏ ‏يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ قَالَتْ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّكَ تُكْثِرُ تَدْعُو بِهَذَا الدُّعَاءِ فَقَالَ إِنَّ قَلْبَ الْآدَمِيِّ بَيْنَ أُصْبُعَيْنِ مِنْ أَصَابِعِ اللَّهِ عَزَّ وَجَلَّ فَإِذَا شَاءَ أَزَاغَهُ وَإِذَا شَاءَ أَقَامَهُ ‏","","",""],[23464,23464,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏نَافِعٌ يَعْنِي ابْنَ عُمَرَ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ حُوسِبَ يَوْمَئِذٍ عُذِّبَ قَالَتْ قُلْتُ يَا رَسُولَ اللَّهِ يَقُولُ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏يُحَاسَبُ حِسَابًا يَسِيرًا ‏} ‏قَالَ ذَاكَ الْعَرْضُ مَنْ نُوقِشَ الْحِسَابَ يَوْمَئِذٍ عُذِّبَ ‏","","",""],[23465,23465,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏سُوَيْدِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏ابْنِ قُرَيْظَةَ الصَّدَفِيِّ ‏ ‏قَالَ قُلْتُ ‏ ‏لِعَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏أَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُضَاجِعُكِ وَأَنْتِ حَائِضٌ قَالَتْ نَعَمْ إِذَا شَدَدْتُ عَلَيَّ إِزَارِي وَلَمْ يَكُنْ لَنَا إِذْ ذَاكَ إِلَّا فِرَاشٌ وَاحِدٌ فَلَمَّا رَزَقَنِي اللَّهُ عَزَّ وَجَلَّ فِرَاشًا آخَرَ اعْتَزَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[23466,23466,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُمْنُ الْمَرْأَةِ تَيْسِيرُ خِطْبَتِهَا وَتَيْسِيرُ ‏ ‏صَدَاقِهَا ‏","","",""],[23467,23467,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانَ جُنُبًا وَأَرَادَ أَنْ يَنَامَ وَهُوَ جُنُبٌ تَوَضَّأَ وُضُوءَهُ لِلصَّلَاةِ قَبْلَ أَنْ يَنَامَ وَكَانَ يَقُولُ ‏ ‏مَنْ أَرَادَ أَنْ يَنَامَ ‏ ‏وَهُوَ جُنُبٌ فَلْيَتَوَضَّأْ وُضُوءَهُ لِلصَّلَاةِ ‏","","",""],[23468,23468,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏الْحَارِثِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ نُعَيْمٍ ‏ ‏عَنْ ‏ ‏مُسْلِمِ بْنِ مِخْرَاقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَ ‏ ‏ذُكِرَ لَهَا أَنَّ نَاسًا يَقْرَءُونَ الْقُرْآنَ فِي اللَّيْلَةِ مَرَّةً أَوْ مَرَّتَيْنِ فَقَالَتْ أُولَئِكَ قَرَءُوا وَلَمْ يَقْرَءُوا كُنْتُ أَقُومُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةَ التَّمَامِ فَكَانَ ‏ ‏يَقْرَأُ سُورَةَ ‏ ‏الْبَقَرَةِ ‏ ‏وَآلِ ‏ ‏عِمْرَانَ ‏ ‏وَالنِّسَاءِ ‏ ‏فَلَا يَمُرُّ بِآيَةٍ فِيهَا تَخَوُّفٌ إِلَّا دَعَا اللَّهَ عَزَّ وَجَلَّ وَاسْتَعَاذَ وَلَا يَمُرُّ بِآيَةٍ فِيهَا اسْتِبْشَارٌ إِلَّا دَعَا اللَّهَ عَزَّ وَجَلَّ وَرَغِبَ إِلَيْهِ ‏","","",""],[23469,23469,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مُصْعَبِ بْنِ شَيْبَةَ ‏ ‏عَنْ ‏ ‏مُسَافِعِ بْنِ عَبْدِ اللَّهِ الْحَجَبِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ امْرَأَةً قَالَتْ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ تَغْتَسِلُ الْمَرْأَةُ إِذَا احْتَلَمَتْ وَأَبْصَرَتْ الْمَاءَ فَقَالَ نَعَمْ فَقَالَتْ لَهَا ‏ ‏عَائِشَةُ ‏ ‏تَرِبَتْ ‏ ‏يَدَاكِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعِيهَا وَهَلْ يَكُونُ الشَّبَهُ إِلَّا مِنْ قِبَلِ ذَلِكَ إِذَا عَلَا مَاؤُهَا مَاءَ الرَّجُلِ أَشْبَهَ أَخْوَالَهُ وَإِذَا عَلَا مَاءُ الرَّجُلِ مَاءَهَا أَشْبَهَهُ ‏","","",""],[23470,23470,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بَكْرُ بْنُ مُضَرَ ‏ ‏عَنْ ‏ ‏ابْنِ الْهَادِ ‏ ‏أَنَّ ‏ ‏زِيَادَ بْنَ أَبِي زِيَادٍ ‏ ‏مَوْلَى ‏ ‏ابْنِ عَيَّاشٍ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏عِرَاكِ بْنِ مَالِكٍ ‏ ‏قَالَ سَمِعْتُهُ يُحَدِّثُ ‏ ‏عُمَرَ بْنَ عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏جَاءَتْنِي مِسْكِينَةٌ تَحْمِلُ ابْنَتَيْنِ لَهَا فَأَطْعَمْتُهَا ثَلَاثَ تَمَرَاتٍ فَأَعْطَتْ كُلَّ وَاحِدَةٍ مِنْهُمَا تَمْرَةً وَرَفَعَتْ إِلَى فِيهَا تَمْرَةً لِتَأْكُلَهَا فَاسْتَطْعَمَتْهَا ابْنَتَاهَا فَشَقَّتْ التَّمْرَةَ الَّتِي كَانَتْ تُرِيدُ أَنْ تَأْكُلَهَا بَيْنَهُمَا قَالَتْ فَأَعْجَبَنِي شَأْنُهَا فَذَكَرْتُ ذَلِكَ الَّذِي صَنَعَتْ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ أَوْجَبَ لَهَا بِهَا الْجَنَّةَ وَأَعْتَقَهَا بِهَا مِنْ النَّارِ ‏","","",""],[23471,23471,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ أَبِي عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ لَيْلَةٍ فَأَرْسَلْتُ ‏ ‏بَرِيرَةَ ‏ ‏فِي ‏ ‏أَثَرِهِ ‏ ‏لِتَنْظُرَ أَيْنَ ذَهَبَ قَالَتْ فَسَلَكَ نَحْوَ ‏ ‏بَقِيعِ الْغَرْقَدِ ‏ ‏فَوَقَفَ فِي أَدْنَى ‏ ‏الْبَقِيعِ ‏ ‏ثُمَّ رَفَعَ يَدَيْهِ ثُمَّ انْصَرَفَ فَرَجَعَتْ إِلَيَّ ‏ ‏بَرِيرَةُ ‏ ‏فَأَخْبَرَتْنِي فَلَمَّا أَصْبَحْتُ سَأَلْتُهُ فَقُلْتُ يَا رَسُولَ اللَّهِ أَيْنَ خَرَجْتَ اللَّيْلَةَ قَالَ ‏ ‏بُعِثْتُ إِلَى أَهْلِ ‏ ‏الْبَقِيعِ ‏ ‏لِأُصَلِّيَ عَلَيْهِمْ ‏","","",""],[23472,23472,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏عُقَيْلٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَعْتَكِفُ ‏ ‏الْعَشْرَ الْأَوَاخِرَ مِنْ رَمَضَانَ حَتَّى تَوَفَّاهُ اللَّهُ ثُمَّ ‏ ‏اعْتَكَفَ ‏ ‏أَزْوَاجُهُ مِنْ بَعْدِهِ ‏","","",""],[23473,23473,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي هِلَالٍ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏مَا صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصَّلَاةَ لِوَقْتِهَا الْآخَرِ مَرَّتَيْنِ حَتَّى قَبَضَهُ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[23474,23474,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ أَبِي عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ النَّاسَ عَامَ حَجَّةِ الْوَدَاعِ فَقَالَ ‏ ‏مَنْ أَحَبَّ أَنْ يَبْدَأَ مِنْكُمْ بِعُمْرَةٍ قَبْلَ الْحَجِّ فَلْيَفْعَلْ وَأَفْرَدَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْحَجَّ وَلَمْ يَعْتَمِرْ ‏","","",""],[23475,23475,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ أَبِي عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كُنْتُ أُحِبُّ أَنْ أَدْخُلَ ‏ ‏الْبَيْتَ ‏ ‏فَأُصَلِّيَ فِيهِ فَأَخَذَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدِي فَأَدْخَلَنِي فِي الْحِجْرِ فَقَالَ لِي ‏ ‏صَلِّي فِي الْحِجْرِ إِذَا أَرَدْتِ دُخُولَ ‏ ‏الْبَيْتِ ‏ ‏فَإِنَّمَا هُوَ قِطْعَةٌ مِنْ ‏ ‏الْبَيْتِ ‏ ‏وَلَكِنَّ قَوْمَكِ ‏ ‏اسْتَقْصَرُوا حِينَ بَنَوْا ‏ ‏الْكَعْبَةَ ‏ ‏فَأَخْرَجُوهُ مِنْ ‏ ‏الْبَيْتِ ‏","","",""],[23476,23476,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ رَبِّهِ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ فِي الْمَرِيضِ ‏ ‏بِسْمِ اللَّهِ بِتُرْبَةِ أَرْضِنَا بِرِيقَةِ بَعْضِنَا ‏ ‏لِيُشْفَى ‏ ‏سَقِيمُنَا ‏ ‏بِإِذْنِ رَبِّنَا ‏","","",""],[23477,23477,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ مُحَمَّدِ بْنِ أَبِي شَيْبَةَ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏عُثْمَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏طَلْحَةُ بْنُ يَحْيَى الْأَنْصَارِيُّ ‏ ‏عَنْ ‏ ‏يُونُسَ الْأَيْلِيِّ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قُبِضَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ابْنُ ثَلَاثٍ وَسِتِّينَ سَنَةً ‏","","",""],[23478,23478,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَفْصٌ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ حَمْزَةَ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِابْنِ الزُّبَيْرِ ‏ ‏فَحَنَّكَهُ ‏ ‏بِتَمْرَةٍ وَقَالَ هَذَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَأَنْتِ ‏ ‏أُمُّ عَبْدِ اللَّهِ ‏","","",""],[23479,23479,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا ‏ ‏مِنْهُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏عَنْ ‏ ‏زَكَرِيَّا ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏الْبَهِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏مَا عَلِمْتُ حَتَّى دَخَلَتْ عَلَيَّ ‏ ‏زَيْنَبُ ‏ ‏بِغَيْرِ إِذْنٍ وَهِيَ غَضْبَى ثُمَّ قَالَتْ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحْسِبُكَ إِذَا قَلَبَتْ لَكَ بُنَيَّةُ ‏ ‏أَبِي بَكْرٍ ‏ ‏ذُرَيِّعَيْهَا ثُمَّ أَقْبَلَتْ إِلَيَّ فَأَعْرَضْتُ عَنْهَا حَتَّى قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دُونَكِ فَانْتَصِرِي فَأَقْبَلْتُ عَلَيْهَا حَتَّى رَأَيْتُهَا قَدْ يَبِسَ رِيقُهَا فِي فَمِهَا مَا تَرُدُّ عَلَيَّ شَيْئًا فَرَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَهَلَّلُ وَجْهُهُ ‏","","",""],[23480,23480,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَفْصٌ ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏ابْنُ جُدْعَانَ ‏ ‏كَانَ فِي الْجَاهِلِيَّةِ يَصِلُ الرَّحِمَ وَيُطْعِمُ الْمَسَاكِينَ فَهَلْ ذَاكَ نَافِعُهُ قَالَ لَا يَا ‏ ‏عَائِشَةُ ‏ ‏إِنَّهُ لَمْ يَقُلْ يَوْمًا رَبِّ اغْفِرْ لِي خَطِيئَتِي يَوْمَ الدِّينِ ‏","","",""],[23481,23481,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَرْمَلَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ شِمَاسَةَ ‏ ‏قَالَ ‏ ‏أَتَيْتُ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْأَلُهَا عَنْ شَيْءٍ فَقَالَتْ أُخْبِرُكَ بِمَا ‏ ‏سَمِعْتُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ فِي بَيْتِي هَذَا ‏ ‏اللَّهُمَّ مَنْ وَلِيَ مِنْ أَمْرِ أُمَّتِي شَيْئًا فَشَقَّ عَلَيْهِمْ فَاشْقُقْ عَلَيْهِ وَمَنْ وَلِيَ مِنْ أَمْرِ أُمَّتِي شَيْئًا فَرَفَقَ بِهِمْ فَارْفُقْ بِهِ ‏","","",""],[23482,23482,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شَدَّادٌ أَبُو عَمَّارٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ نِسْوَةً مِنْ أَهْلِ ‏ ‏الْبَصْرَةِ ‏ ‏دَخَلْنَ عَلَيْهَا ‏ ‏فَأَمَرَتْهُنَّ أَنْ ‏ ‏يَسْتَنْجِينَ ‏ ‏بِالْمَاءِ وَقَالَتْ مُرْنَ أَزْوَاجَكُنَّ بِذَلِكَ فَإِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَفْعَلُهُ ‏ ‏وَهُوَ شِفَاءٌ مِنْ ‏ ‏الْبَاسُورِ ‏ ‏عَائِشَةُ ‏ ‏تَقُولُهُ ‏ ‏أَوْ ‏ ‏أَبُو عَمَّارٍ ‏","","",""],[23483,23483,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْجَبَّارِ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بَقِيَّةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ الْأَلْهَانِيِّ ‏ ‏سَمِعَ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي قَيْسٍ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عَائِشَةَ ‏ ‏تَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْوِصَالِ ‏ ‏فِي الصِّيَامِ ‏","","",""],[23484,23484,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِدْرِيسَ يَعْنِي الشَّافِعِيَّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏أَنَّهُ قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏كَمْ كُفِّنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ فِي ثَلَاثَةِ أَثْوَابٍ بِيضٍ ‏ ‏سُحُولِيَّةٍ ‏","","",""],[23485,23485,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِدْرِيسَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏يَزِيدَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏كَمْ كَانَ ‏ ‏صَدَاقُ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ كَانَ ‏ ‏صَدَاقُهُ ‏ ‏لِأَزْوَاجِهِ اثْنَتَيْ عَشْرَةَ أُوقِيَّةً ‏ ‏وَنَشًّا ‏ ‏قَالَتْ أَتَدْرِي مَا ‏ ‏النَّشُّ ‏ ‏قُلْتُ لَا قَالَتْ نِصْفُ أُوقِيَّةٍ فَتِلْكَ خَمْسُ مِائَةِ دِرْهَمٍ فَهَذَا ‏ ‏صَدَاقُ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِأَزْوَاجِهِ ‏","","",""],[23486,23486,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏أَشْعَثُ بْنُ سُلَيْمٍ ‏ ‏أَخْبَرَنِي قَالَ سَمِعَ ‏ ‏أَبَاهُ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَهَا قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحِبُّ التَّيَمُّنَ فِي شَأْنِهِ كُلِّهِ مَا اسْتَطَاعَ فِي طُهُورِهِ ‏ ‏وَتَرَجُّلِهِ ‏ ‏وَتَنَعُّلِهِ ‏ ‏قَالَ ‏ ‏فَلَمَّا قَدِمَ ‏ ‏الْأَشْعَثُ ‏ ‏الْكُوفَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحِبُّ التَّيَمُّنَ مَا اسْتَطَاعَ ‏","","",""],[23487,23487,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏الْأَشْعَثِ بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏قَالَ قُلْتُ ‏ ‏لِعَائِشَةَ ‏ ‏أَيُّ الْعَمَلِ كَانَ أَحَبَّ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ ‏ ‏الدَّائِمُ قُلْتُ فَأَيُّ سَاعَةٍ كَانَ يَقُومُ قَالَتْ إِذَا سَمِعَ الصَّرْخَةَ ‏","","",""],[23488,23488,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعْدُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُرْوَةَ بْنَ الزُّبَيْرِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي وَأَنَا بَيْنَهُ وَبَيْنَ الْقِبْلَةِ ‏","","",""],[23489,23489,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَقُولُ فِي رُكُوعِهِ وَسُجُودِهِ سُبُّوحٌ قُدُّوسٌ رَبُّ الْمَلَائِكَةِ وَالرُّوحِ ‏","","",""],[23490,23490,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏أَرْسَلَ إِلَيْنَا آلُ ‏ ‏أَبِي بَكْرٍ ‏ ‏بِقَائِمَةِ شَاةٍ لَيْلًا فَأَمْسَكْتُ وَقَطَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ قَالَتْ أَمْسَكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَطَعْتُ ‏ ‏قَالَتْ تَقُولُ لِلَّذِي تُحَدِّثُهُ هَذَا عَلَى غَيْرِ مِصْبَاحٍ قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏إِنَّهُ لَيَأْتِي عَلَى آلِ ‏ ‏مُحَمَّدٍ ‏ ‏الشَّهْرُ مَا يَخْتَبِزُونَ خُبْزًا وَلَا يَطْبُخُونَ قِدْرًا ‏ ‏قَالَ ‏ ‏حُمَيْدٌ ‏ ‏فَذَكَرْتُ ‏ ‏لِصَفْوَانَ بْنِ مُحْرِزٍ ‏ ‏فَقَالَ ‏ ‏لَا بَلْ كُلُّ شَهْرَيْنِ ‏","","",""],[23491,23491,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَشْعَثُ بْنُ سُلَيْمٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَاهُ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَيْهَا وَعِنْدَهَا رَجُلٌ قَالَ فَتَغَيَّرَ وَجْهُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَأَنَّهُ شَقَّ عَلَيْهِ فَقَالَتْ يَا رَسُولَ اللَّهِ أَخِي فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏انْظُرْنَ مَا إِخْوَانُكُنَّ فَإِنَّمَا الرَّضَاعَةُ مِنْ الْمَجَاعَةِ ‏","","",""],[23492,23492,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏أَنَّ امْرَأَةً سَأَلَتْ ‏ ‏عَائِشَةَ ‏ ‏إِحْدَانَا تَحِيضُ أَتُجْزِئُ صَلَاتَهَا فَقَالَتْ ‏ ‏أَحَرُورِيَّةٌ ‏ ‏أَنْتِ قَدْ كُنَّا نَحِيضُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَا نَفْعَلُ ذَلِكَ ‏","","",""],[23493,23493,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الَّذِي يَقْرَأُ الْقُرْآنَ الْمَاهِرَ بِهِ مَعَ السَّفَرَةِ الْكِرَامِ الْبَرَرَةِ وَالَّذِي يَقْرَؤُهُ تَشْتَدُّ عَلَيْهِ قِرَاءَتُهُ فَلَهُ أَجْرَانِ ‏","","",""],[23494,23494,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَتْ ‏ ‏سَوْدَةُ ‏ ‏امْرَأَةً ‏ ‏ثَبِطَةً ‏ ‏ثَقِيلَةً ‏ ‏فَاسْتَأْذَنَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ تُفِيضَ مِنْ ‏ ‏جَمْعٍ ‏ ‏قَبْلَ أَنْ تَقِفَ فَأَذِنَ لَهَا ‏ ‏قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏وَدِدْتُ أَنِّي كُنْتُ اسْتَأْذَنْتُهُ فَأَذِنَ لِي ‏ ‏وَكَانَ ‏ ‏الْقَاسِمُ ‏ ‏يَكْرَهُ أَنْ ‏ ‏يُفِيضَ ‏ ‏قَبْلَ أَنْ يَقِفَ ‏","","",""],[23495,23495,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏أَنَّ ‏ ‏سَعْدَ بْنَ هِشَامٍ ‏ ‏حَدَّثَهُ قَالَ قُلْتُ ‏ ‏يَا ‏ ‏أُمَّ الْمُؤْمِنِينَ ‏ ‏حَدِّثِينِي عَنْ ‏ ‏خُلُقِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ أَلَسْتَ تَقْرَأُ الْقُرْآنَ قَالَ قُلْتُ بَلَى ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏قَالَتْ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا صَلَّى صَلَاةً دَاوَمَ عَلَيْهَا وَكَانَ إِذَا فَاتَهُ الْقِيَامُ مِنْ اللَّيْلِ غَلَبَتْهُ عَيْنَاهُ بِنَوْمٍ أَوْ وَجَعٍ صَلَّى ثِنْتَيْ عَشْرَةَ رَكْعَةً مِنْ النَّهَارِ قَالَتْ وَلَمْ يَقُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةً يُتِمُّهَا حَتَّى الصَّبَاحِ وَلَمْ ‏ ‏يَقْرَإِ الْقُرْآنَ فِي لَيْلَةٍ يُتِمُّهُ وَلَمْ يَصُمْ شَهْرًا يُتِمُّهُ غَيْرَ رَمَضَانَ حَتَّى مَاتَ ‏","","",""],[23496,23496,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَهُ ‏ ‏يَا ابْنَ أُخْتِي إِنَّ ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ يَعْنِي ابْنَ عُمَرَ ‏ ‏أَخْطَأَ سَمْعُهُ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَكَرَ رَجُلًا يُعَذَّبُ فِي قَبْرِهِ بِعَمَلِهِ وَأَهْلُهُ يَبْكُونَ عَلَيْهِ وَإِنَّهَا وَاللَّهِ مَا ‏ ‏تَزِرُ ‏ ‏وَازِرَةٌ ‏ ‏وِزْرَ ‏ ‏أُخْرَى ‏","","",""],[23497,23497,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏قَالَتْ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏كَمْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الضُّحَى قَالَتْ أَرْبَعَ رَكَعَاتٍ وَيَزِيدُ مَا شَاءَ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[23498,23498,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مُرْنَ أَزْوَاجَكُنَّ يَغْسِلُوا عَنْهُمْ أَثَرَ ‏ ‏الْخَلَاءِ ‏ ‏وَالْبَوْلِ فَإِنَّا ‏ ‏نَسْتَحْيِي أَنْ ‏ ‏نَنْهَاهُمْ عَنْ ذَلِكَ وَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَفْعَلُهُ ‏","","",""],[23499,23499,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏لَيْثٌ ‏ ‏وَثَابِتٌ ‏ ‏عَنْ ‏ ‏سُمَيَّةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَجَدَ عَلَى ‏ ‏صَفِيَّةَ بِنْتَ حُيَيٍّ ‏ ‏فِي شَيْءٍ فَقَالَتْ ‏ ‏صَفِيَّةُ ‏ ‏يَا ‏ ‏عَائِشَةُ ‏ ‏أَرْضِي عَنِّي رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَكِ يَوْمِي فَقَالَتْ نَعَمْ فَأَخَذَتْ خِمَارًا لَهَا مَصْبُوغًا بِزَعْفَرَانٍ فَرَشَّتْهُ بِالْمَاءِ لِيَفُوحَ رِيحُهُ فَقَعَدَتْ إِلَى جَنْبِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَيْكِ يَا ‏ ‏عَائِشَةُ ‏ ‏إِنَّهُ لَيْسَ يَوْمَكِ قَالَتْ ذَلِكَ فَضْلُ اللَّهِ ‏ ‏يُؤْتِيهِ مَنْ يَشَاءُ وَأَخْبَرَتْهُ بِالْأَمْرِ فَرَضِيَ عَنْهَا ‏","","",""],[23500,23500,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏صَخْرُ بْنُ جُوَيْرِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ الْمَكِّيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو خَلَفٍ ‏ ‏مَوْلَى ‏ ‏بَنِي جُمَحٍ ‏ ‏أَنَّهُ دَخَلَ مَعَ ‏ ‏عُبَيْدِ بْنِ عُمَيْرٍ ‏ ‏عَلَى ‏ ‏عَائِشَةَ أُمِّ الْمُؤْمِنِينَ ‏ ‏فِي سَقِيفَةِ ‏ ‏زَمْزَمَ ‏ ‏لَيْسَ فِي الْمَسْجِدِ ظِلٌّ غَيْرَهَا فَقَالَتْ مَرْحَبًا وَأَهْلًا ‏ ‏بِأَبِي عَاصِمٍ يَعْنِي عُبَيْدَ بْنَ عُمَيْرٍ ‏ ‏مَا يَمْنَعُكَ أَنْ تَزُورَنَا ‏ ‏أَوْ تُلِمَّ بِنَا ‏ ‏فَقَالَ أَخْشَى أَنْ أُمِلَّكِ فَقَالَتْ مَا كُنْتَ تَفْعَلُ قَالَ جِئْتُ أَنْ أَسْأَلَكِ عَنْ آيَةٍ فِي كِتَابِ اللَّهِ عَزَّ وَجَلَّ كَيْفَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَؤُهَا فَقَالَتْ أَيَّةُ آيَةٍ فَقَالَ الَّذِينَ يُؤْتُونَ مَا أَتَوْا أَوْ الَّذِينَ يَأْتُونَ مَا أَتَوْا فَقَالَتْ أَيَّتُهُمَا أَحَبُّ إِلَيْكَ قَالَ قُلْتُ وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَإِحْدَاهُمَا أَحَبُّ إِلَيَّ مِنْ الدُّنْيَا جَمِيعًا ‏ ‏أَوْ الدُّنْيَا وَمَا فِيهَا ‏ ‏قَالَتْ أَيَّتُهُمَا قُلْتُ ‏ { ‏الَّذِينَ يَأْتُونَ مَا أَتَوْا ‏} ‏قَالَتْ أَشْهَدُ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَذَلِكَ كَانَ يَقْرَؤُهَا وَكَذَلِكَ أُنْزِلَتْ ‏ ‏أَوْ قَالَتْ أَشْهَدُ لَكَذَلِكَ أُنْزِلَتْ وَكَذَلِكَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَؤُهَا ‏ ‏وَلَكِنَّ الْهِجَاءَ حَرْفٌ ‏","","",""],[23501,23501,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي وَهِيَ مُعْتَرِضَةٌ عَنْ يَمِينِهِ وَعَنْ شِمَالِهِ ‏","","",""],[23502,23502,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ يَحْيَى الضَّبِّيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَالَ فَقَامَ ‏ ‏عُمَرُ ‏ ‏خَلْفَهُ بِكُوزٍ فَقَالَ مَا هَذَا يَا ‏ ‏عُمَرُ ‏ ‏قَالَ مَاءٌ تَوَضَّأْ بِهِ يَا رَسُولَ اللَّهِ قَالَ ‏ ‏مَا أُمِرْتُ كُلَّمَا بُلْتُ أَنْ أَتَوَضَّأَ وَلَوْ فَعَلْتُ ذَلِكَ كَانَتْ سُنَّةً ‏","","",""],[23503,23503,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تُحَرِّمُ الْمَصَّةُ وَلَا الْمَصَّتَانِ ‏","","",""],[23504,23504,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏وَاللَّهِ ‏ ‏مَا تَرَكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَكْعَتَيْنِ بَعْدَ الْعَصْرِ عِنْدِي قَطُّ ‏","","",""],[23505,23505,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏نَزَلَتْ عَلَى ‏ ‏صَفِيَّةَ أُمِّ طَلْحَةَ الطَّلَحَاتِ ‏ ‏فَرَأَتْ بَنَاتٍ لَهَا يُصَلِّينَ بِغَيْرِ ‏ ‏خُمُرٍ ‏ ‏قَدْ حِضْنَ قَالَ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏لَا تُصَلِّيَنَّ ‏ ‏جَارِيَةٌ ‏ ‏مِنْهُنَّ إِلَّا فِي ‏ ‏خِمَارٍ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَيَّ وَكَانَتْ فِي حِجْرِي ‏ ‏جَارِيَةٌ ‏ ‏فَأَلْقَى عَلَيَّ ‏ ‏حَقْوَهُ ‏ ‏فَقَالَ شُقِّيهِ بَيْنَ هَذِهِ وَبَيْنَ الْفَتَاةِ الَّتِي فِي حِجْرِ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏فَإِنِّي لَا أُرَاهَا إِلَّا قَدْ حَاضَتْ ‏ ‏أَوْ لَا ‏ ‏أُرَاهُمَا إِلَّا قَدْ حَاضَتَا ‏","","",""],[23506,23506,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فِي مَرَضِهِ ‏ ‏مُرُوا ‏ ‏أَبَا بَكْرٍ ‏ ‏فَلْيُصَلِّ بِالنَّاسِ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏لِحَفْصَةَ ‏ ‏إِنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏رَجُلٌ رَقِيقٌ فَإِذَا قَامَ فِي مَقَامِكَ لَمْ يُسْمِعْ النَّاسَ مِنْ الْبُكَاءِ فَقَالَ مُرُوهُ أَنْ يُصَلِّيَ بِالنَّاسِ قَالَ فَرَدَّتْ عَلَيْهِ مِرَارًا كُلُّ ذَلِكَ يَقُولُ مُرُوا ‏ ‏أَبَا بَكْرٍ ‏ ‏يُصَلِّي بِالنَّاسِ فَقَالَ فِي الثَّالِثَةِ دَعِينِي فَإِنَّكُنَّ أَنْتُنَّ صَوَاحِبُ ‏ ‏يُوسُفَ ‏ ‏لِيَؤُمَّ ‏ ‏أَبُو بَكْرٍ ‏ ‏النَّاسَ ‏","","",""],[23507,23507,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَادَ أَنْ يَغْتَسِلَ مِنْ جَنَابَةٍ يَغْسِلُ يَدَيْهِ ثَلَاثًا ثُمَّ يَأْخُذُ بِيَمِينِهِ لِيَصُبَّ عَلَى شِمَالِهِ فَيَغْسِلُ فَرْجَهُ حَتَّى يُنَقِّيَهُ ثُمَّ يَغْسِلُ يَدَهُ غَسْلًا حَسَنًا ثُمَّ يُمَضْمِضُ ثَلَاثًا وَيَسْتَنْشِقُ ثَلَاثًا وَيَغْسِلُ وَجْهَهُ ثَلَاثًا وَذِرَاعَيْهِ ثَلَاثًا ثُمَّ يَصُبُّ عَلَى رَأْسِهِ الْمَاءَ ثَلَاثًا ثُمَّ يَغْتَسِلُ فَإِذَا خَرَجَ غَسَلَ قَدَمَيْهِ ‏","","",""],[23508,23508,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏خَمْسُ نِسْوَةٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏","","",""],[23509,23509,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُحِرَ لَهُ حَتَّى كَانَ يُخَيَّلُ إِلَيْهِ أَنَّهُ يَصْنَعُ الشَّيْءَ وَلَمْ يَصْنَعْ حَتَّى إِذَا كَانَ ذَاتَ يَوْمٍ رَأَيْتُهُ يَدْعُو فَقَالَ شَعَرْتُ ‏ ‏أَنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ أَفْتَانِي فِيمَا اسْتَفْتَيْتُهُ فِيهِ فَقَالَ أَتَانِي رَجُلَانِ فَقَعَدَ أَحَدُهُمَا عِنْدَ رَأْسِي وَالْآخَرُ عِنْدَ رِجْلِي فَقَالَ أَحَدُهُمَا مَا وَجَعُ الرَّجُلِ قَالَ الْآخَرُ ‏ ‏مَطْبُوبٌ ‏ ‏قَالَ مَنْ ‏ ‏طَبَّهُ ‏ ‏قَالَ ‏ ‏لَبِيدُ بْنُ الْأَعْصَمِ ‏ ‏قَالَ فِي مَاذَا قَالَ فِي مُشْطٍ ‏ ‏وَمُشَاطَةٍ ‏ ‏وَجُبِّ ‏ ‏أَوْ جُفِّ ‏ ‏طَلْعَةِ ‏ ‏ذَكَرٍ ‏ ‏قَالَ فَأَيْنَ هُوَ قَالَ فِي ‏ ‏ذِي أَرْوَانَ ‏ ‏قَالَ فَانْطَلَقَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا رَجَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْبَرَ ‏ ‏عَائِشَةَ ‏ ‏قَالَ وَكَأَنَّ نَخْلَهَا رُءُوسُ الشَّيَاطِينِ وَكَأَنَّ مَاءَهَا نُقَاعَةُ الْحِنَّاءِ فَقُلْتُ يَا رَسُولَ اللَّهِ فَأَخْرَجْتَهُ لِلنَّاسِ فَقَالَ أَمَّا اللَّهُ عَزَّ وَجَلَّ فَقَدْ شَفَانِي وَخَشِيتُ أَنْ أُثَوِّرَ عَلَى النَّاسِ مِنْهُ شَرًّا ‏","","",""],[23510,23510,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أُمِّ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فِي رَجُلٍ طَلَّقَ امْرَأَتَهُ ثَلَاثًا ثُمَّ تَزَوَّجَهَا آخَرُ ثُمَّ طَلَّقَهَا مِنْ قَبْلِ أَنْ ‏ ‏يَمَسَّهَا ‏ ‏قَالَ ‏ ‏لَا يَنْكِحُهَا الْأَوَّلُ حَتَّى تَذُوقَ مِنْ ‏ ‏عُسَيْلَتِهِ ‏ ‏وَيَذُوقَ مِنْ ‏ ‏عُسَيْلَتِهَا ‏","","",""],[23511,23511,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْبِتْعِ ‏ ‏وَالْبِتْعُ ‏ ‏نَبِيذُ ‏ ‏الْعَسَلِ ‏ ‏وَكَانَ أَهْلُ ‏ ‏الْيَمَنِ ‏ ‏يَشْرَبُونَهُ فَقَالَ ‏ ‏كُلُّ شَرَابٍ أَسْكَرَ فَهُوَ حَرَامٌ ‏","","",""],[23512,23512,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أَبِي خَالِدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الشَّعْبِيَّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏قَدْ خَيَّرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نِسَاءَهُ أَفَكَانَ طَلَاقًا ‏","","",""],[23513,23513,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ أَبِي حَازِمٍ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَمَّا أَتَتْ عَلَى ‏ ‏الْحَوْأَبِ ‏ ‏سَمِعَتْ نُبَاحَ الْكِلَابِ فَقَالَتْ مَا أَظُنُّنِي إِلَّا رَاجِعَةٌ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَنَا ‏ ‏أَيَّتُكُنَّ تَنْبَحُ عَلَيْهَا كِلَابُ ‏ ‏الْحَوْأَبِ ‏ ‏فَقَالَ لَهَا ‏ ‏الزُّبَيْرُ ‏ ‏تَرْجِعِينَ عَسَى اللَّهُ عَزَّ وَجَلَّ أَنْ يُصْلِحَ بِكِ بَيْنَ النَّاسِ ‏","","",""],[23514,23514,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏أَنَّ ‏ ‏أَبَا مُوسَى ‏ ‏قَالَ ‏ ‏لِعَائِشَةَ ‏ ‏إِنِّي أُرِيدُ أَنْ أَسْأَلَكِ عَنْ شَيْءٍ وَأَنَا ‏ ‏أَسْتَحْيِي مِنْكِ فَقَالَتْ سَلْ وَلَا تَسْتَحْيِ فَإِنَّمَا أَنَا أُمُّكَ فَسَأَلَهَا عَنْ الرَّجُلِ ‏ ‏يَغْشَى ‏ ‏وَلَا يُنْزِلُ فَقَالَتْ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَصَابَ الْخِتَانُ الْخِتَانَ فَقَدْ وَجَبَ الْغُسْلُ ‏","","",""],[23515,23515,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عِمْرَانَ يَعْنِي الْقَرِيعِيَّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَمَّاسٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَائِشَةَ ‏ ‏تُحَدِّثُ ‏ ‏تَقُولُ ‏ ‏نَهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْحَنْتَمِ ‏ ‏وَهُوَ ‏ ‏الْجَرُّ ‏ ‏وَالدُّبَّاءِ ‏ ‏وَالنَّقِيرِ ‏ ‏وَعَنْ ‏ ‏الْمُزَفَّتِ ‏","","",""],[23516,23516,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏خَالِدًا ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ يَزِيدَ ‏ ‏رَضِيعِ ‏ ‏عَائِشَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَا مِنْ رَجُلٍ مُسْلِمٍ ‏ ‏يُصَلِّي عَلَيْهِ أُمَّةٌ مِنْ النَّاسِ كُلُّهُمْ يَشْفَعُ لَهُ إِلَّا شُفِّعُوا فِيهِ ‏","","",""],[23517,23517,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حُصَيْنُ بْنُ نَافِعٍ الْمَازِنِيُّ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏حُصَيْنٌ ‏ ‏هَذَا صَالِحُ الْحَدِيثِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْحَسَنُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ هِشَامٍ ‏ ‏أَنَّهُ ‏ ‏دَخَلَ عَلَى ‏ ‏أُمِّ الْمُؤْمِنِينَ عَائِشَةَ ‏ ‏فَسَأَلَهَا عَنْ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ كَانَ ‏ ‏يُصَلِّي مِنْ اللَّيْلِ ‏ ‏ثَمَانِيَ رَكَعَاتٍ ‏ ‏وَيُوتِرُ ‏ ‏بِالتَّاسِعَةِ وَيُصَلِّي رَكْعَتَيْنِ وَهُوَ جَالِسٌ وَذَكَرَتْ الْوُضُوءَ أَنَّهُ كَانَ يَقُومُ إِلَى صَلَاتِهِ فَيَأْمُرُ بِطَهُورِهِ وَسِوَاكِهِ فَلَمَّا ‏ ‏بَدَّنَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى سِتَّ رَكَعَاتٍ ‏ ‏وَأَوْتَرَ ‏ ‏بِالسَّابِعَةِ وَصَلَّى رَكْعَتَيْنِ وَهُوَ جَالِسٌ قَالَتْ فَلَمْ يَزَلْ عَلَى ذَلِكَ حَتَّى قُبِضَ قُلْتُ إِنِّي أُرِيدُ أَنْ أَسْأَلَكِ عَنْ ‏ ‏التَّبَتُّلِ ‏ ‏فَمَا تَرَيْنَ فِيهِ قَالَتْ فَلَا تَفْعَلْ أَمَا سَمِعْتَ اللَّهَ عَزَّ وَجَلَّ يَقُولُ ‏ { ‏وَلَقَدْ أَرْسَلْنَا رُسُلًا مِنْ قَبْلِكَ وَجَعَلْنَا لَهُمْ أَزْوَاجًا وَذُرِّيَّةً ‏} ‏فَلَا ‏ ‏تَبَتَّلْ ‏ ‏فَخَرَجَ وَقَدْ فَقُهَ فَقَدِمَ ‏ ‏الْبَصْرَةَ ‏ ‏فَلَمْ يَلْبَثْ إِلَّا يَسِيرًا حَتَّى خَرَجَ إِلَى أَرْضِ ‏ ‏مُكْرَانَ ‏ ‏فَقُتِلَ هُنَاكَ عَلَى أَفْضَلِ عَمَلِهِ ‏","","",""],[23518,23518,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏أَبِي مَعْشَرٍ ‏ ‏عَنْ ‏ ‏النَّخَعِيِّ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَفْرُكُهُ مِنْ ثَوْبِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدِي فَإِذَا رَأَيْتَهُ فَاغْسِلْهُ فَإِنْ خَفِيَ عَلَيْكَ فَارْشُشْهُ ‏","","",""],[23519,23519,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ سُئِلَ عَنْ الْمَرْأَةِ تَقْضِي الصَّلَاةَ أَيَّامَ مَحِيضِهَا ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏أَنَّ امْرَأَةً سَأَلَتْ عَنْ ذَلِكَ ‏ ‏عَائِشَةَ ‏ ‏فَقَالَتْ ‏ ‏أَحَرُورِيَّةٌ ‏ ‏أَنْتِ لَقَدْ كُنَّا نَحِيضُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَا نَقْضِي شَيْئًا مِنْ الصَّلَاةِ ‏","","",""],[23520,23520,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏خَمْسٌ ‏ ‏فَوَاسِقُ ‏ ‏يُقْتَلْنَ فِي الْحِلِّ وَالْحَرَمِ الْحَيَّةُ وَالْغُرَابُ ‏ ‏الْأَبْقَعُ ‏ ‏وَالْفَأْرَةُ ‏ ‏وَالْكَلْبُ ‏ ‏الْعَقُورُ ‏ ‏وَالْحِدَأَةُ ‏","","",""],[23521,23521,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏امْرَأَةِ ابْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏فِي الَّذِي يَشْرَبُ فِي إِنَاءِ فِضَّةٍ كَأَنَّمَا ‏ ‏يُجَرْجِرُ ‏ ‏فِي بَطْنِهِ نَارًا ‏","","",""],[23522,23522,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏إِنْسَانٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ لِلْقَبْرِ ضَغْطَةً لَوْ كَانَ أَحَدٌ نَاجِيًا مِنْهَا نَجَا ‏ ‏سَعْدُ بْنُ مُعَاذٍ ‏","","",""],[23523,23523,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُرْوَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَقَدْ ‏ ‏رَأَيْتُنِي بَيْنَ يَدَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَهُ وَبَيْنَ الْقِبْلَةِ وَهُوَ ‏ ‏يُصَلِّي ‏ ‏قَالَ ‏ ‏سَعْدٌ ‏ ‏وَأَحْسِبُهُ قَالَ وَهِيَ حَائِضٌ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏سَعْدٌ ‏ ‏الَّذِي يَشُكُّ ‏","","",""],[23524,23524,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ يَزِيدَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏مَا شَبِعَ آلُ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ خُبْزِ شَعِيرٍ يَوْمَيْنِ مُتَتَابِعَيْنِ حَتَّى قُبِضَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[23525,23525,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏أَوْفَى بْنِ دَلْهَمٍ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَنَالُ شَيْئًا مِنْ وُجُوهِنَا وَهُوَ صَائِمٌ ‏","","",""],[23526,23526,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏إِمْلَاءً عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏الْمَاهِرُ ‏ ‏بِالْقُرْآنِ مَعَ السَّفَرَةِ الْكِرَامِ ‏ ‏الْبَرَرَةِ ‏ ‏وَهَذَا الَّذِي يَقْرَؤُهُ وَهُوَ عَلَيْهِ شَاقٌّ يَتَتَعْتَعُ فِيهِ لَهُ أَجْرَانِ اثْنَانِ ‏","","",""],[23527,23527,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏بَكْرٍ ‏ ‏قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُقَبِّلُ وَهُوَ صَائِمٌ وَأَيُّكُمْ ‏ ‏أَمْلَكُ ‏ ‏لِإِرْبِهِ ‏ ‏مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[23528,23528,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏قَالَ سَأَلْتُ ‏ ‏أُمَّ الْمُؤْمِنِينَ ‏ ‏عَنْ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ اللَّيْلِ فَقَالَتْ كَانَ ‏ ‏يُصَلِّي لَيْلًا طَوِيلًا قَائِمًا وَلَيْلًا طَوِيلًا قَاعِدًا فَإِذَا قَرَأَ قَائِمًا رَكَعَ قَائِمًا وَإِذَا قَرَأَ قَاعِدًا رَكَعَ قَاعِدًا ‏","","",""],[23529,23529,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي حَفْصَةَ ‏ ‏مَوْلَى ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏أَخْبَرَتْهُ أَنَّهُ ‏ ‏لَمَّا كَسَفَتْ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَتَوَضَّأَ وَأَمَرَ ‏ ‏فَنُودِيَ إِنَّ الصَّلَاةَ جَامِعَةٌ فَقَامَ فَأَطَالَ الْقِيَامَ فِي صَلَاتِهِ قَالَتْ فَأَحْسِبُهُ قَرَأَ سُورَةَ ‏ ‏الْبَقَرَةِ ‏ ‏ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ ثُمَّ قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ ثُمَّ قَامَ مِثْلَ مَا قَامَ وَلَمْ يَسْجُدْ ثُمَّ رَكَعَ فَسَجَدَ ثُمَّ قَامَ فَصَنَعَ مِثْلَ مَا صَنَعَ ثُمَّ رَكَعَ رَكْعَتَيْنِ فِي سَجْدَةٍ ثُمَّ جَلَسَ وَجُلِّيَ عَنْ الشَّمْسِ ‏","","",""],[23530,23530,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏الْأَشْعَثِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ مَعْقِلٍ الْمُحَارِبِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَائِشَةَ ‏ ‏تَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏يُنْتَبَذَ ‏ ‏فِي ‏ ‏الدُّبَّاءِ ‏ ‏وَالْحَنْتَمِ ‏ ‏وَالْمُزَفَّتِ ‏","","",""],[23531,23531,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏طَيَّبْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِإِحْرَامِهِ حِينَ أَحْرَمَ وَلِحِلِّهِ حِينَ أَحَلَّ ‏ ‏بِمِنًى ‏ ‏قَبْلَ أَنْ ‏ ‏يُفِيضَ ‏","","",""],[23532,23532,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏وَدِدْتُ أَنِّي كُنْتُ ‏ ‏اسْتَأْذَنْتُ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَمَا اسْتَأْذَنَتْهُ ‏ ‏سَوْدَةُ ‏ ‏فَأُصَلِّي الصُّبْحَ ‏ ‏بِمِنًى ‏ ‏وَأُوَافِي قَبْلَ أَنْ يَجِيءَ النَّاسُ فَقَالُوا ‏ ‏لِعَائِشَةَ ‏ ‏وَاسْتَأْذَنَتْهُ ‏ ‏سَوْدَةُ ‏ ‏قَالَتْ إِنَّهَا كَانَتْ امْرَأَةً ثَقِيلَةً ‏ ‏ثَبِطَةً ‏ ‏فَأَذِنَ لَهَا ‏","","",""],[23533,23533,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏صَفِيَّةَ ‏ ‏حَاضَتْ ‏ ‏بِمِنًى ‏ ‏وَقَدْ ‏ ‏أَفَاضَتْ ‏ ‏فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏يَا رَسُولَ اللَّهِ ‏ ‏مَا أُرَى ‏ ‏صَفِيَّةَ ‏ ‏إِلَّا ‏ ‏حَابِسَتَنَا ‏ ‏قَالَ لِمَ قُلْتُ حَاضَتْ قَالَ أَوَلَمْ تَكُنْ قَدْ ‏ ‏أَفَاضَتْ ‏ ‏قُلْتُ ‏ ‏قَالَ أَظُنُّهُ قَالَتْ بَلَى شَكَّ ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏قَالَ فَلَا ‏ ‏حَبْسَ ‏ ‏عَلَيْكِ فَارْتَحِلِي ‏","","",""],[23534,23534,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّازِقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏طَلْحَةَ بْنِ يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي وَعَلَيْهِ ‏ ‏مِرْطٌ ‏ ‏مِنْ هَذِهِ الْمُرَحَّلَاتِ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي وَعَلَيْهِ بَعْضُهُ وَعَلَيَّ بَعْضُهُ وَالْمِرْطُ مِنْ أَكْسِيَةٍ سُودٍ ‏","","",""],[23535,23535,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ الْخَفَّافُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُلَيْمَانُ التَّيْمِيُّ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏أُمَيْنَةُ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا سُئِلَتْ عَنْ ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏فَقَالَتْ تَعْجِزُ إِحْدَاكُنَّ أَنْ تَتَّخِذَ مِنْ أُضْحِيَّتِهَا ‏ ‏سِقَاءً ‏ ‏ثُمَّ قَالَتْ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ مَنَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏وَكَذَا وَكَذَا ‏ ‏نَسِيَهُ ‏ ‏سُلَيْمَانُ ‏","","",""],[23536,23536,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ الْخَفَّافُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ أَكْمَلَ الْمُؤْمِنِينَ إِيمَانًا أَحْسَنُهُمْ خُلُقًا وَأَلْطَفُهُمْ بِأَهْلِهِ ‏","","",""],[23537,23537,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏مَوْلَى ‏ ‏دَوْسٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَائِشَةَ ‏ ‏تَقُولُ ‏ ‏لِعَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ ‏ ‏أَسْبِغْ ‏ ‏الْوُضُوءَ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏وَيْلٌ ‏ ‏لِلْأَعْقَابِ ‏ ‏مِنْ النَّارِ ‏","","",""],[23538,23538,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْقَاسِمُ بْنُ الْفَضْلِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَلِيٍّ أَبِي جَعْفَرٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا ‏ ‏كَانَتْ ‏ ‏تَدَّانُ ‏ ‏فَقِيلَ لَهَا مَا لَكِ وَلِلدَّيْنِ فَقَالَتْ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ عَبْدٍ كَانَتْ لَهُ نِيَّةٌ فِي أَدَاءِ دَيْنِهِ إِلَّا كَانَ لَهُ مِنْ اللَّهِ عَزَّ وَجَلَّ عَوْنٌ فَأَنَا أَلْتَمِسُ ذَلِكَ الْعَوْنَ ‏","","",""],[23539,23539,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا وَائِلٍ ‏ ‏يُحَدِّثُ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا ‏ ‏تَصَدَّقَتْ ‏ ‏الْمَرْأَةُ مِنْ بَيْتِ زَوْجِهَا كَانَ لَهَا بِهِ أَجْرٌ وَلِلزَّوْجِ مِثْلُ ذَلِكَ وَلِلْخَازِنِ مِثْلُ ذَلِكَ وَلَا يَنْقُصُ كُلُّ وَاحِدٍ مِنْهُمَا مِنْ أَجْرِ صَاحِبِهِ شَيْئًا لِلزَّوْجِ بِمَا اكْتَسَبَ وَلَهَا بِمَا أَنْفَقَتْ ‏","","",""],[23540,23540,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَقَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصْبِحُ جُنُبًا ثُمَّ يَغْتَسِلُ ثُمَّ ‏ ‏يَغْدُو ‏ ‏إِلَى الْمَسْجِدِ وَرَأْسُهُ يَقْطُرُ ثُمَّ يَصُومُ ذَلِكَ الْيَوْمَ ‏ ‏فَأَخْبَرْتُ ‏ ‏مَرْوَانَ بْنَ الْحَكَمِ ‏ ‏بِقَوْلِهَا فَقَالَ لِي أَخْبِرْ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏بِقَوْلِ ‏ ‏عَائِشَةَ ‏ ‏فَقُلْتُ إِنَّهُ لِي صَدِيقٌ فَأُحِبُّ أَنْ تُعْفِيَنِي فَقَالَ ‏ ‏عَزَمْتُ ‏ ‏عَلَيْكَ لَمَا انْطَلَقْتَ إِلَيْهِ فَانْطَلَقْتُ أَنَا وَهُوَ إِلَى ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏فَأَخْبَرْتُهُ بِقَوْلِهَا فَقَالَ ‏ ‏عَائِشَةُ ‏ ‏إِذَنْ أَعْلَمُ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[23541,23541,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏دَخَلَ عَلَيْهَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدَهَا يَوْمَ فِطْرٍ ‏ ‏أَوْ أَضْحًى ‏ ‏وَعِنْدَهَا ‏ ‏جَارِيَتَانِ ‏ ‏تَضْرِبَانِ بِدُفَّيْنِ ‏ ‏فَانْتَهَرَهُمَا ‏ ‏أَبُو بَكْرٍ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعْنَا يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏إِنَّ لِكُلِّ قَوْمٍ عِيدًا وَإِنَّ عِيدَنَا هَذَا الْيَوْمَ ‏","","",""],[23542,23542,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏مُعْتَكِفًا ‏ ‏فِي الْمَسْجِدِ فَتَجِيءُ ‏ ‏عَائِشَةُ ‏ ‏فَيُخْرِجُ رَأْسَهُ فَتُرَجِّلُهُ وَهِيَ حَائِضٌ ‏","","",""],[23543,23543,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حُصَيْنٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يَسَافٍ ‏ ‏عَنْ ‏ ‏فَرْوَةَ بْنِ نَوْفَلٍ ‏ ‏قَالَ قُلْتُ ‏ ‏لِعَائِشَةَ ‏ ‏أَخْبِرِينِي بِدُعَاءٍ كَانَ يَدْعُو بِهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ كَانَ يُكْثِرُ أَنْ يَقُولَ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ مَا عَمِلْتُ وَمَنْ شَرِّ مَا لَمْ أَعْمَلْ ‏","","",""],[23544,23544,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي الضُّحَى ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يُكْثِرُ أَنْ يَقُولَ فِي رُكُوعِهِ وَسُجُودِهِ ‏ ‏سُبْحَانَكَ اللَّهُمَّ رَبَّنَا وَبِحَمْدِكَ اللَّهُمَّ اغْفِرْ لِي ‏","","",""],[23545,23545,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏قَالَتْ لِي ‏ ‏عَمْرَةُ ‏ ‏أَعْطِنِي قِطْعَةً مِنْ أَرْضِكَ أُدْفَنْ فِيهَا فَإِنِّي سَمِعْتُ ‏ ‏عَائِشَةَ ‏ ‏تَقُولُ ‏ ‏كَسْرُ عَظْمِ الْمَيِّتِ مِثْلُ كَسْرِ عَظْمِ الْحَيِّ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏وَكَانَ ‏ ‏مَوْلًى ‏ ‏مِنْ أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏يُحَدِّثُهُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[23546,23546,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَمَّتِهِ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا طَلَعَ الْفَجْرُ صَلَّى رَكْعَتَيْنِ ‏ ‏أَوْ لَمْ يُصَلِّ إِلَّا رَكْعَتَيْنِ ‏ ‏أَقُولُ يَقْرَأُ فِيهِمَا ‏ ‏بِفَاتِحَةِ الْكِتَابِ ‏","","",""],[23547,23547,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏بُدَيْلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏قَالَ ‏ ‏كُنْتُ ‏ ‏شَاكِيًا ‏ ‏بِفَارِسَ ‏ ‏فَكُنْتُ أُصَلِّي قَاعِدًا فَسَأَلْتُ عَنْ ذَلِكَ ‏ ‏عَائِشَةَ ‏ ‏فَقَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي لَيْلًا طَوِيلًا قَائِمًا وَلَيْلًا طَوِيلًا قَاعِدًا فَإِذَا قَرَأَ قَائِمًا رَكَعَ ‏ ‏أَوْ خَشَعَ ‏ ‏قَائِمًا وَإِذَا قَرَأَ قَاعِدًا رَكَعَ قَاعِدًا ‏","","",""],[23548,23548,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي التَّيَّاحِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سُلَيْمَانَ بْنَ مَرْثَدٍ ‏ ‏أَوْ ‏ ‏مَزْيَدٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي مِنْ اللَّيْلِ تِسْعَ رَكَعَاتٍ ‏","","",""],[23549,23549,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏خَيْثَمَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي عَطِيَّةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏إِنِّي لَأَعْلَمُ كَيْفَ كَانَتْ تَلْبِيَةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ سَمِعْتُهَا بَعْدَ ذَلِكَ لَبَّتْ ‏ ‏لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ ‏","","",""],[23550,23550,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الضُّحَى ‏ ‏يُحَدِّثُ عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏مِنْ كُلِّ اللَّيْلِ قَدْ ‏ ‏أَوْتَرَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاسْتَقَرَّ ‏ ‏وِتْرُهُ ‏ ‏إِلَى ‏ ‏السَّحَرِ ‏","","",""],[23551,23551,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الضُّحَى ‏ ‏يُحَدِّثُ عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏لَمَّا أُنْزِلَتْ الْآيَاتُ الْأَوَاخِرُ مِنْ سُورَةِ ‏ ‏الْبَقَرَةِ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَرَأَهُنَّ فِي الْمَسْجِدِ فَحَرَّمَ التِّجَارَةَ فِي الْخَمْرِ ‏","","",""],[23552,23552,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ بَحْرٍ ‏ ‏حَدَّثَنَا ‏ ‏الدَّرَاوَرْدِيُّ ‏ ‏قَالَ ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏حَدَّثَنِي عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُسْتَقَى لَهُ الْمَاءُ الْعَذْبُ مِنْ بُيُوتِ السُّقْيَا ‏","","",""],[23553,23553,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏رُفِعَ الْقَلَمُ عَنْ ثَلَاثٍ عَنْ النَّائِمِ حَتَّى ‏ ‏يَسْتَيْقِظَ وَعَنْ الصَّبِيِّ حَتَّى ‏ ‏يَحْتَلِمَ ‏ ‏وَعَنْ الْمَجْنُونِ حَتَّى يَعْقِلَ ‏ ‏وَقَدْ ‏ ‏قَالَ ‏ ‏حَمَّادٌ ‏ ‏وَعَنْ الْمَعْتُوهِ حَتَّى يَعْقِلَ ‏","","",""],[23554,23554,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏سُلَيْمَانُ الْأَعْمَشُ ‏ ‏أَخْبَرَنِي عَنْ ‏ ‏ثَابِتٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْقَاسِمَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏نَاوِلِينِي ‏ ‏الْخُمْرَةَ ‏ ‏قَالَتْ إِنِّي حَائِضٌ قَالَ إِنَّهَا لَيْسَتْ فِي يَدِكِ ‏","","",""],[23555,23555,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏الْقَاسِمُ بْنُ الْفَضْلِ ‏ ‏قَالَ قَالَ ‏ ‏الْحَسَنُ ‏ ‏قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏يَا رَسُولَ اللَّهِ هَلْ تَذْكُرُونَ أَهْلِيكُمْ يَوْمَ الْقِيَامَةِ قَالَ ‏ ‏أَمَّا فِي مَوَاطِنَ ثَلَاثَةٍ فَلَا الْكِتَابُ وَالْمِيزَانُ وَالصِّرَاطُ ‏","","",""],[23556,23556,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْقَاسِمُ بْنُ الْفَضْلِ ‏ ‏قَالَ قَالَ ‏ ‏الْحَسَنُ ‏ ‏قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏يَا رَسُولَ اللَّهِ ‏ { ‏يَوْمَ تُبَدَّلُ الْأَرْضُ غَيْرَ الْأَرْضِ وَالسَّمَوَاتُ ‏} ‏أَيْنَ النَّاسُ قَالَ إِنَّ هَذَا لَشَيْءٌ مَا سَأَلَنِي عَنْهُ أَحَدٌ مِنْ أُمَّتِي قَبْلَكِ النَّاسُ عَلَى الصِّرَاطِ ‏","","",""],[23557,23557,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بِشْرٌ يَعْنِي ابْنَ مُفَضَّلٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَلَمَةُ بْنُ عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏قَالَ ‏ ‏نُبِّئْتُ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏يُصَلِّي فِي ‏ ‏شُعُرِنَا ‏ ‏قَالَ ‏ ‏بِشْرٌ ‏ ‏هُوَ الثَّوْبُ الَّذِي يُلْبَسُ تَحْتَ ‏ ‏الدِّثَارِ ‏","","",""],[23558,23558,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُطَرِّفٌ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏قَالَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيَظَلُّ صَائِمًا ثُمَّ يُقَبِّلُ مَا شَاءَ مِنْ وَجْهِي حَتَّى يُفْطِرَ ‏","","",""],[23559,23559,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَتَوَضَّأُ إِذَا أَرَادَ أَنْ يَغْتَسِلَ مِنْ الْجَنَابَةِ وُضُوءَهُ لِلصَّلَاةِ ثُمَّ يُدْخِلُ يَدَهُ فِي الْإِنَاءِ فَيَتَتَبَّعُ أُصُولَ شَعَرِهِ فَإِذَا ظَنَّ أَنْ قَدْ ‏ ‏اسْتَبْرَأَ ‏ ‏الْبَشَرَةَ كُلَّهَا أَفْرَغَ عَلَى رَأْسِهِ ثَلَاثًا ثُمَّ يَغْتَسِلُ ‏ ‏و قَالَ ‏ ‏عُرْوَةُ ‏ ‏غَيْرَ أَنَّهُ يَبْدَأُ فَيَغْسِلُ يَدَهُ ثُمَّ فَرْجَهُ ‏","","",""],[23560,23560,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏عَامِرٍ الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏إِنْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيَبِيتُ جُنُبًا فَيَأْتِيهِ ‏ ‏بِلَالٌ ‏ ‏لِصَلَاةِ ‏ ‏الْغَدَاةِ ‏ ‏فَيَقُومُ فَيَغْتَسِلُ وَإِنِّي لَأَنْظُرُ إِلَى الْمَاءِ يَنْحَدِرُ فِي جِلْدِهِ وَشَعَرِهِ فَأَسْمَعُ قِرَاءَتَهُ لِصَلَاةِ ‏ ‏الْغَدَاةِ ‏ ‏ثُمَّ يَظَلُّ صَائِمًا ‏ ‏قَالَ ‏ ‏مُطَرِّفٌ ‏ ‏قُلْتُ ‏ ‏لِعَامِرٍ ‏ ‏فِي رَمَضَانَ قَالَ سَوَاءٌ عَلَيْكَ ‏","","",""],[23561,23561,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَهْدِيٌّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وَاصِلٌ الْأَحْدَبُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ النَّخَعِيِّ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ بْنِ يَزِيدَ ‏ ‏قَالَ ‏ ‏رَأَتْنِي ‏ ‏عَائِشَةُ أُمُّ الْمُؤْمِنِينَ ‏ ‏أَغْسِلُ أَثَرَ جَنَابَةٍ أَصَابَتْ ثَوْبِي فَقَالَتْ مَا هَذَا قُلْتُ جَنَابَةٌ أَصَابَتْ ثَوْبِي فَقَالَتْ لَقَدْ رَأَيْتُنَا وَإِنَّهُ يُصِيبُ ثَوْبَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَا يَزِيدُ عَلَى أَنْ يَقُولَ بِهِ هَكَذَا ‏ ‏وَوَصَفَهُ ‏ ‏مَهْدِيٌّ ‏ ‏حَكَّ يَدَهُ عَلَى الْأُخْرَى ‏","","",""],[23562,23562,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏وَعَفَّانُ ‏ ‏وَرَوْحٌ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏رُفِعَ الْقَلَمُ عَنْ ثَلَاثَةٍ عَنْ الصَّبِيِّ حَتَّى يَحْتَلِمَ وَعَنْ النَّائِمِ حَتَّى يَسْتَيْقِظَ وَعَنْ الْمَعْتُوهِ حَتَّى يَعْقِلَ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏وَعَنْ الْمَجْنُونِ حَتَّى يَعْقِلَ ‏ ‏وَقَدْ ‏ ‏قَالَ ‏ ‏حَمَّادٌ ‏ ‏وَعَنْ الْمَعْتُوهِ حَتَّى يَعْقِلَ ‏ ‏وَقَالَ ‏ ‏رَوْحٌ ‏ ‏وَعَنْ الْمَجْنُونِ حَتَّى يَعْقِلَ ‏","","",""],[23563,23563,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أُمِّ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُهْدِيَتْ لَهُ هَدِيَّةٌ فِيهَا ‏ ‏قِلَادَةٌ ‏ ‏مِنْ جَزْعٍ فَقَالَ ‏ ‏لَأَدْفَعَنَّهَا إِلَى أَحَبِّ أَهْلِي إِلَيَّ فَقَالَتْ النِّسَاءُ ذَهَبَتْ بِهَا ‏ ‏ابْنَةُ أَبِي قُحَافَةَ ‏ ‏فَدَعَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُمَامَةَ بِنْتَ زَيْنَبَ ‏ ‏فَعَلَّقَهَا فِي عُنُقِهَا ‏","","",""],[23564,23564,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْرُجُ إِلَى الصَّلَاةِ وَرَأْسُهُ يَقْطُرُ كَانَ جُنُبًا فَاغْتَسَلَ وَهُوَ يُرِيدُ الصَّوْمَ ‏","","",""],[23565,23565,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏قَالَ سَأَلْتُ ‏ ‏الْأَسْوَدَ بْنَ يَزِيدَ ‏ ‏عَمَّا ‏ ‏حَدَّثَتْهُ ‏ ‏عَائِشَةُ ‏ ‏عَنْ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ كَانَ ‏ ‏يَنَامُ أَوَّلَ اللَّيْلِ ‏ ‏وَيُحْيِي آخِرَهُ ثُمَّ إِنْ كَانَتْ لَهُ حَاجَةٌ إِلَى أَهْلِهِ قَضَى حَاجَتَهُ ثُمَّ قَامَ قَبْلَ أَنْ يَمَسَّ مَاءً فَإِذَا كَانَ عِنْدَ النِّدَاءِ الْأَوَّلِ قَالَتْ ‏ ‏وَثَبَ ‏ ‏وَلَا وَاللَّهِ مَا قَالَتْ قَامَ ‏ ‏فَأَفَاضَ ‏ ‏عَلَيْهِ الْمَاءَ وَلَا وَاللَّهِ مَا قَالَتْ اغْتَسَلَ وَأَنَا أَعْلَمُ بِمَا تُرِيدُ وَإِنْ لَمْ يَكُنْ جُنُبًا تَوَضَّأَ وُضُوءَ الرَّجُلِ لِلصَّلَاةِ ثُمَّ صَلَّى الرَّكْعَتَيْنِ ‏","","",""],[23566,23566,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَابِسِ بْنِ رَبِيعَةَ ‏ ‏قَالَ قُلْتُ ‏ ‏لِعَائِشَةَ ‏ ‏هَلْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَرَّمَ لُحُومَ ‏ ‏الْأَضَاحِيِّ ‏ ‏بَعْدَ ثَلَاثٍ قَالَتْ لَا وَلَكِنْ لَمْ يَكُنْ يُضَحِّي مِنْهُنَّ إِلَّا قَلِيلٌ فَفَعَلَ ذَلِكَ لِيُطْعِمَ مَنْ ضَحَّى مَنْ لَمْ يُضَحِّ ‏ ‏وَلَقَدْ رَأَيْتُنَا نُخَبِّئُ ‏ ‏الْكُرَاعَ ‏ ‏مِنْ أَضَاحِيِّنَا ثُمَّ نَأْكُلُهَا بَعْدَ عَشْرٍ ‏","","",""],[23567,23567,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏قَالَ ‏ ‏أَتَيْتُ ‏ ‏الْأَسْوَدَ بْنَ يَزِيدَ ‏ ‏وَكَانَ لِي أَخًا وَصَدِيقًا فَقُلْتُ ‏ ‏أَبَا عَمْرٍو ‏ ‏حَدِّثْنِي مَا ‏ ‏حَدَّثَتْكَ ‏ ‏أُمُّ الْمُؤْمِنِينَ ‏ ‏عَنْ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ قَالَتْ كَانَ ‏ ‏يَنَامُ أَوَّلَ اللَّيْلِ ‏ ‏وَيُحْيِي آخِرَهُ فَرُبَّمَا كَانَتْ لَهُ حَاجَةٌ إِلَى أَهْلِهِ ثُمَّ يَنَامُ قَبْلَ أَنْ يَمَسَّ مَاءً فَإِذَا كَانَ عِنْدَ النِّدَاءِ الْأَوَّلِ ‏ ‏وَثَبَ ‏ ‏وَمَا قَالَتْ قَامَ ‏ ‏فَأَفَاضَ ‏ ‏عَلَيْهِ الْمَاءَ وَمَا قَالَتْ اغْتَسَلَ وَأَنَا أَعْلَمُ مَا تُرِيدُ وَإِنْ لَمْ يَكُنْ جُنُبًا تَوَضَّأَ وُضُوءَ الرَّجُلِ لِلصَّلَاةِ ‏","","",""],[23568,23568,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏قَالَ قَالَ ‏ ‏لِي ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏حَدِّثْنِي ‏ ‏بَعْضَ مَا كَانَتْ تُسِرُّ إِلَيْكَ ‏ ‏أُمُّ الْمُؤْمِنِينَ ‏ ‏فَرُبَّ شَيْءٍ كَانَتْ تُحَدِّثُكَ بِهِ تَكْتُمُهُ النَّاسَ قَالَ قُلْتُ لَقَدْ حَدَّثَتْنِي حَدِيثًا حَفِظْتُ أَوَّلَهُ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْلَا أَنَّ قَوْمَكِ حَدِيثٌ عَهْدُهُمْ بِجَاهِلِيَّةٍ ‏ ‏أَوْ قَالَ بِكُفْرٍ ‏ ‏قَالَ يَقُولُ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏لَنَقَضْتُ ‏ ‏الْكَعْبَةَ ‏ ‏فَجَعَلْتُ لَهَا بَابَيْنِ فِي الْأَرْضِ بَابًا يُدْخَلُ مِنْهُ وَبَابًا يُخْرَجُ مِنْهُ ‏ ‏قَالَ ‏ ‏أَبُو إِسْحَاقَ ‏ ‏فَأَنَا رَأَيْتُهَا كَذَلِكَ ‏","","",""],[23569,23569,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَفْتِلُ ‏ ‏قَلَائِدَ ‏ ‏هَدْيِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَا يَدَعُ حَاجَةً لَهُ إِلَى امْرَأَةٍ حَتَّى يَرْجِعَ الْحَاجُّ ‏ ‏حَدَّثَنَا ‏ ‏بِهِ ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏قَالَ ‏ ‏وَمَا يَدَعُ حَاجَةً إِنْ كَانَتْ لَهُ إِلَى امْرَأَةٍ حَتَّى يَرْجِعَ الْحَاجُّ ‏","","",""],[23570,23570,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ ثَوْبَانَ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ أُمَّ الْمُؤْمِنِينَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَحْرُمُ مِنْ الرَّضَاعِ مَا يَحْرُمُ مِنْ النَّسَبِ مِنْ خَالٍ أَوْ عَمٍّ أَوْ ابْنِ أَخٍ ‏","","",""],[23571,23571,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قِيلَ يَا رَسُولَ اللَّهِ مَاتَتْ فُلَانَةُ وَاسْتَرَاحَتْ فَغَضِبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏إِنَّمَا يَسْتَرِيحُ مَنْ غُفِرَ لَهُ ‏","","",""],[23572,23572,"","","‏ ‏حَدَّثَنَا ‏ ‏سَكَنُ بْنُ نَافِعٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏صَالِحُ بْنُ أَبِي الْأَخْضَرِ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَادَ أَنْ يَنَامَ وَهُوَ جُنُبٌ تَوَضَّأَ وُضُوءَهُ لِلصَّلَاةِ فَإِذَا أَرَادَ أَنْ يَأْكُلَ أَوْ يَشْرَبَ غَسَلَ كَفَّيْهِ ثُمَّ يَأْكُلُ أَوْ ‏ ‏يَشْرَبُ إِنْ شَاءَ ‏","","",""],[23573,23573,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي مِنْ اللَّيْلِ ثَلَاثَ عَشْرَةَ سَجْدَةً وَكَانَ أَكْثَرَ صَلَاتِهِ قَائِمًا فَلَمَّا كَبُرَ وَثَقُلَ كَانَ أَكْثَرَ صَلَاتِهِ قَاعِدًا وَكَانَ ‏ ‏يُصَلِّي صَلَاتَهُ وَأَنَا مُعْتَرِضَةٌ بَيْنَ يَدَيْهِ عَلَى الْفِرَاشِ الَّذِي يَرْقُدُ عَلَيْهِ حَتَّى يُرِيدَ أَنْ ‏ ‏يُوتِرَ ‏ ‏فَيَغْمِزُنِي فَأَقُومُ ‏ ‏فَيُوتِرُ ‏ ‏ثُمَّ يَضْطَجِعُ حَتَّى يَسْمَعَ النِّدَاءَ بِالصَّلَاةِ ثُمَّ يَقُومُ فَيَسْجُدُ سَجْدَتَيْنِ خَفِيفَتَيْنِ ثُمَّ يُلْصِقُ جَنْبَهُ الْأَرْضَ ثُمَّ يَخْرُجُ إِلَى الصَّلَاةِ ‏","","",""],[23574,23574,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يُحَاسَبُ يَوْمَ الْقِيَامَةِ أَحَدٌ فَيُغْفَرَ لَهُ يَرَى الْمُسْلِمُ عَمَلَهُ فِي قَبْرِهِ وَيَقُولُ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏فَيَوْمَئِذٍ لَا يُسْأَلُ عَنْ ذَنْبِهِ إِنْسٌ وَلَا جَانٌّ ‏} { ‏يُعْرَفُ الْمُجْرِمُونَ بِسِيمَاهُمْ ‏}","","",""],[23575,23575,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَنَامُ وَهُوَ ‏ ‏جُنُبٌ ‏ ‏إِذَا تَوَضَّأَ وُضُوءَهُ لِلصَّلَاةِ ‏","","",""],[23576,23576,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بُكَيْرٌ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏جَعَلْتُ عَلَى بَابِ بَيْتِي سِتْرًا فِيهِ ‏ ‏تَصَاوِيرُ ‏ ‏فَلَمَّا أَقْبَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِيَدْخُلَ ‏ ‏نَظَرَ إِلَيْهِ فَهَتَكَهُ قَالَتْ فَأَخَذْتُهُ فَقَطَعْتُ مِنْهُ ‏ ‏نُمْرُقَتَيْنِ ‏ ‏فَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْتَفِقُهُمَا ‏","","",""],[23577,23577,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُمَرُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ قُلْتُ ‏ ‏لِعَائِشَةَ ‏ ‏أَكُنْتِ تَغْتَسِلِينَ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ نَعَمْ كُنْتُ ‏ ‏أَغْتَسِلُ أَنَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ إِنَاءٍ وَاحِدٍ ‏","","",""],[23578,23578,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُمَرُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏رُمِيتُ بِمَا رُمِيتُ بِهِ وَأَنَا غَافِلَةٌ فَبَلَغَنِي بَعْدَ ذَلِكَ ‏ ‏رَضْخٌ ‏ ‏مِنْ ذَلِكَ فَبَيْنَمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدِي إِذْ أُوحِيَ إِلَيْهِ وَكَانَ إِذَا أُوحِيَ إِلَيْهِ يَأْخُذُهُ شِبْهُ السُّبَاتِ فَبَيْنَمَا هُوَ جَالِسٌ عِنْدِي إِذْ أُنْزِلَ عَلَيْهِ الْوَحْيُ فَرَفَعَ رَأْسَهُ وَهُوَ يَمْسَحُ عَنْ جَبِينِهِ فَقَالَ ‏ ‏أَبْشِرِي يَا ‏ ‏عَائِشَةُ ‏ ‏فَقُلْتُ بِحَمْدِ اللَّهِ عَزَّ وَجَلَّ لَا بِحَمْدِكَ فَقَرَأَ ‏ { ‏الَّذِينَ يَرْمُونَ ‏ ‏الْمُحْصَنَاتِ ‏ ‏حَتَّى بَلَغَ ‏ ‏مُبَرَّءُونَ مِمَّا يَقُولُونَ ‏}","","",""],[23579,23579,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَمَّا أُنْزِلَ الْخِيَارُ قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي أُرِيدُ أَنْ أَذْكُرَ لَكِ أَمْرًا لَا ‏ ‏تَقْضِينَ فِيهِ شَيْئًا حَتَّى ‏ ‏تَسْتَأْمِرِي ‏ ‏أَبَوَيْكِ قُلْتُ مَا هُوَ فَقَرَأَ ‏ ‏آيَةَ الْخِيَارِ ‏ ‏فَقُلْتُ بَلْ أَخْتَارُ اللَّهَ عَزَّ وَجَلَّ وَرَسُولَهُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَفَرِحَ بِذَلِكَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[23580,23580,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْوَلَاءُ ‏ ‏لِمَنْ أَعْتَقَ ‏","","",""],[23581,23581,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏وَعَبْدُ الصَّمَدِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ثَابِتٌ أَبُو زَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏إِنَّ ‏ ‏عَائِشَةَ ‏ ‏حَدَّثَتْهَا قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَغْتَسِلُ أَنَا وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ إِنَاءٍ وَاحِدٍ فَأُبَادِرُهُ وَأَقُولُ دَعْ لِي دَعْ لِي ‏","","",""],[23582,23582,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ جَعْفَرٍ ‏ ‏وَالْخُزَاعِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَتْنَا ‏ ‏أُمُّ بَكْرٍ بِنْتُ الْمِسْوَرِ ‏ ‏قَالَ ‏ ‏الْخُزَاعِيُّ ‏ ‏عَنْ ‏ ‏أُمِّ بَكْرٍ بِنْتِ الْمِسْوَرِ ‏ ‏أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ ‏ ‏بَاعَ أَرْضًا لَهُ مِنْ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏بِأَرْبَعِينَ ‏ ‏أَلْفَ دِينَارٍ فَقَسَمَهُ فِي فُقَرَاءِ ‏ ‏بَنِي زُهْرَةَ ‏ ‏وَفِي ‏ ‏الْمُهَاجِرِينَ ‏ ‏وَأُمَّهَاتِ الْمُؤْمِنِينَ قَالَ ‏ ‏الْمِسْوَرُ ‏ ‏فَأَتَيْتُ ‏ ‏عَائِشَةَ ‏ ‏بِنَصِيبِهَا فَقَالَتْ مَنْ أَرْسَلَ بِهَذَا فَقُلْتُ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَتْ أَمَا إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏وَقَالَ ‏ ‏الْخُزَاعِيُّ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏يَحْنُو عَلَيْكُنَّ بَعْدِي إِلَّا الصَّابِرُونَ سَقَى اللَّهُ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ ‏ ‏مِنْ سَلْسَبِيلِ الْجَنَّةِ ‏","","",""],[23583,23583,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ حَزْمٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُقْطَعُ الْيَدُ إِلَّا فِي رُبُعِ دِينَارٍ فَصَاعِدًا ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏قَالَ ثَنَا ‏ ‏يَزِيدُ بْنُ عَبْدِ اللَّه ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ حَزْمٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّه ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مِثْلَهُ سَوَاءً ‏","","",""],[23584,23584,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ الْخُزَاعِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ نَوْفَلٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُرْوَةُ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ مُهِلًّا بِالْحَجِّ ‏","","",""],[23585,23585,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ الْخُزَاعِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَقْرَأُ عَلَى نَفْسِهِ ‏ ‏الْمُعَوِّذَاتِ ‏ ‏وَيَنْفُثُ ‏ ‏قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَلَمَّا اشْتَكَى ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَعَلْتُ أَقْرَأُ عَلَيْهِ وَأَمْسَحُهُ بِكَفِّهِ رَجَاءَ بَرَكَةِ يَدِهِ ‏","","",""],[23586,23586,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْرَدَ الْحَجَّ ‏","","",""],[23587,23587,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَبْدِ اللَّهِ بْنِ قُسَيْطٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ ثَوْبَانَ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ أَنْ ‏ ‏يُسْتَمْتَعَ ‏ ‏بِجُلُودِ الْمَيْتَةِ إِذَا ‏ ‏دُبِغَتْ ‏","","",""],[23588,23588,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أُرَجِّلُ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏مُعْتَكِفٌ ‏ ‏وَكَانَ لَا يَدْخُلُ الْبَيْتَ إِلَّا لِحَاجَةِ الْإِنْسَانِ ‏","","",""],[23589,23589,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏فَقُلْتُ كَيْفَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي رَمَضَانَ قَالَتْ ‏ ‏كَانَتْ صَلَاتُهُ فِي رَمَضَانَ وَغَيْرِ رَمَضَانَ وَاحِدَةً كَانَ ‏ ‏يُصَلِّي إِحْدَى عَشْرَةَ رَكْعَةً ‏ ‏يُصَلِّي أَرْبَعًا فَلَا تَسْأَلْ عَنْ حُسْنِهِنَّ وَطُولِهِنَّ ثُمَّ ‏ ‏يُصَلِّي أَرْبَعَ رَكَعَاتٍ فَلَا تَسْأَلْ عَنْ حُسْنِهِنَّ وَطُولِهِنَّ ثُمَّ ‏ ‏يُصَلِّي ثَلَاثَ رَكَعَاتٍ فَقُلْتُ يَا رَسُولَ اللَّهِ تَنَامُ قَبْلَ أَنْ ‏ ‏تُوتِرَ ‏ ‏فَقَالَ إِنَّ عَيْنَيَّ تَنَامَانِ وَقَلْبِي لَا يَنَامُ ‏","","",""],[23590,23590,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏بَكْرُ بْنُ مُضَرَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُوسَى بْنُ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ بْنِ سَهْلٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ أَنَا ‏ ‏وَعُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏يَوْمًا عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَقَالَتْ لَوْ رَأَيْتُمَا نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ فِي مَرَضٍ مَرِضَهُ قَالَتْ وَكَانَ لَهُ عِنْدِي سِتَّةُ دَنَانِيرَ ‏ ‏قَالَ ‏ ‏مُوسَى ‏ ‏أَوْ سَبْعَةٌ ‏ ‏قَالَتْ ‏ ‏فَأَمَرَنِي نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ أُفَرِّقَهَا قَالَتْ فَشَغَلَنِي وَجَعُ نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى عَافَاهُ اللَّهُ قَالَتْ ثُمَّ سَأَلَنِي عَنْهَا فَقَالَ مَا فَعَلَتْ السِّتَّةُ ‏ ‏قَالَ أَوْ السَّبْعَةُ ‏ ‏قُلْتُ لَا وَاللَّهِ لَقَدْ كَانَ شَغَلَنِي وَجَعُكَ قَالَتْ فَدَعَا بِهَا ثُمَّ صَفَّهَا فِي كَفِّهِ فَقَالَ مَا ظَنُّ نَبِيِّ اللَّهِ لَوْ لَقِيَ اللَّهَ عَزَّ وَجَلَّ وَهَذِهِ عِنْدَهُ ‏","","",""],[23591,23591,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ يَعْنِي ابْنَ بِلَالٍ ‏ ‏عَنْ ‏ ‏شَرِيكٍ يَعْنِي ابْنَ أَبِي نَمِرٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهَا يَا ‏ ‏عَائِشَةُ ‏ ‏ارْفُقِي فَإِنَّ اللَّهَ إِذَا أَرَادَ بِأَهْلِ بَيْتٍ خَيْرًا دَلَّهُمْ ‏ ‏عَلَى بَابِ الرِّفْقِ ‏","","",""],[23592,23592,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏عَنْ ‏ ‏شَرِيكِ بْنِ أَبِي نَمِرٍ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي عَتِيقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فِي عَجْوَةِ ‏ ‏الْعَالِيَةِ ‏ ‏أَوَّلَ ‏ ‏الْبُكْرَةِ ‏ ‏عَلَى رِيقِ النَّفْسِ شِفَاءٌ مِنْ كُلِّ سِحْرٍ أَوْ سُمٍّ ‏","","",""],[23593,23593,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَ ‏ ‏أُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِضَبٍّ فَلَمْ يَأْكُلْهُ وَلَمْ يَنْهَ عَنْهُ قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏أَفَلَا نُطْعِمُهُ الْمَسَاكِينَ قَالَ لَا تُطْعِمُوهُمْ مِمَّا لَا تَأْكُلُونَ ‏","","",""],[23594,23594,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ يَعْنِي ابْنَ جَعْفَرٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي عَتِيقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فِي الْعَجْوَةِ ‏ ‏الْعَالِيَةِ ‏ ‏شِفَاءٌ ‏ ‏أَوْ إِنَّهَا تِرْيَاقٌ ‏ ‏أَوَّلَ ‏ ‏الْبُكْرَةِ ‏","","",""],[23595,23595,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْقَاسِمُ بْنُ الْفَضْلِ الْحُدَّانِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُحَمَّدَ بْنَ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ الزُّبَيْرِ ‏ ‏يَقُولُ حَدَّثَتْنِي ‏ ‏عَائِشَةُ أُمُّ الْمُؤْمِنِينَ ‏ ‏قَالَتْ ‏ ‏بَيْنَمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَائِمٌ إِذْ ضَحِكَ فِي مَنَامِهِ ثُمَّ اسْتَيْقَظَ فَقُلْتُ يَا رَسُولَ اللَّهِ مِمَّ ضَحِكْتَ قَالَ ‏ ‏إِنَّ أُنَاسًا مِنْ أُمَّتِي يَؤُمُّونَ هَذَا ‏ ‏الْبَيْتَ ‏ ‏لِرَجُلٍ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏قَدْ اسْتَعَاذَ ‏ ‏بِالْحَرَمِ ‏ ‏فَلَمَّا بَلَغُوا ‏ ‏الْبَيْدَاءَ ‏ ‏خُسِفَ بِهِمْ مَصَادِرُهُمْ شَتَّى يَبْعَثُهُمْ اللَّهُ عَلَى نِيَّاتِهِمْ قُلْتُ وَكَيْفَ يَبْعَثُهُمْ اللَّهُ عَزَّ وَجَلَّ عَلَى نِيَّاتِهِمْ وَمَصَادِرُهُمْ شَتَّى قَالَ جَمَعَهُمْ الطَّرِيقُ مِنْهُمْ الْمُسْتَبْصِرُ وَابْنُ السَّبِيلِ وَالْمَجْبُورُ يَهْلِكُونَ مَهْلِكًا وَاحِدًا ‏ ‏وَيَصْدُرُونَ ‏ ‏مَصَادِرَ شَتَّى ‏","","",""],[23596,23596,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي الرِّجَالِ ‏ ‏مِنْ ‏ ‏بَنِي النَّجَّارِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الرِّجَالِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كَسْرُ عَظْمِ الْمَيِّتِ كَكَسْرِهِ حَيًّا ‏","","",""],[23597,23597,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَيْتٌ لَيْسَ فِيهِ تَمْرٌ كَأَنَّ لَيْسَ فِيهِ طَعَامٌ ‏","","",""],[23598,23598,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي الرِّجَالِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ نَقِيعِ ‏ ‏الْبُسْرِ ‏ ‏وَهُوَ ‏ ‏الزَّهْوُ ‏","","",""],[23599,23599,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الرِّجَالِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏جَاءَتْ امْرَأَةٌ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ بِأَبِي وَأُمِّي ‏ ‏ابْتَعْتُ ‏ ‏أَنَا وَابْنِي مِنْ فُلَانٍ ثَمَرَةَ أَرْضِهِ فَأَتَيْنَاهُ نَسْتَوْضِعُهُ وَاللَّهِ مَا أَصَبْنَا مِنْ ثَمَرِهِ شَيْئًا إِلَّا شَيْئًا أَكَلْنَا فِي بُطُونِنَا أَوْ نُطْعِمُهُ مِسْكِينًا رَجَاءَ الْبَرَكَةِ فَحَلَفَ أَنْ لَا يَفْعَلَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَأَلَّى ‏ ‏أَنْ لَا يَفْعَلَ خَيْرًا ‏ ‏تَأَلَّى ‏ ‏أَنْ لَا يَفْعَلَ خَيْرًا ‏ ‏تَأَلَّى ‏ ‏أَنْ لَا يَفْعَلَ خَيْرًا فَبَلَغَ ذَلِكَ الرَّجُلَ فَأَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنْ شِئْتَ الثَّمَرَ كُلَّهُ وَإِنْ شِئْتَ مَا وَضَعُوا فَوَضَعَ عَنْهُمْ مَا وَضَعُوا ‏","","",""],[23600,23600,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الرِّجَالِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَلَفَ أَنْ لَا يَدْخُلَ عَلَى نِسَائِهِ شَهْرًا فَلَمَّا كَانَ تِسْعَةٌ وَعِشْرُونَ مِنْ الشَّهْرِ جَاءَ لِيَدْخُلَ فَقُلْتُ لَهُ أَلَمْ تَحْلِفْ شَهْرًا فَقَالَ إِنَّ الشَّهْرَ تِسْعَةٌ وَعِشْرُونَ ‏","","",""]];
